function dsSyncDiagNoteDrop(path, kind, stats){
  try{
    if(!stats) return;
    stats.droppedCount = Number(stats.droppedCount || 0) + 1;
    const safeKind = String(kind || 'invalid');
    stats.droppedKinds = stats.droppedKinds || {};
    stats.droppedKinds[safeKind] = Number(stats.droppedKinds[safeKind] || 0) + 1;
    if(path && (!stats.droppedPaths || stats.droppedPaths.length < 8)){
      (stats.droppedPaths || (stats.droppedPaths = [])).push(String(path));
    }
  }catch(_){ }
}
function dsSanitizeCloudPayload(value, path, seen, stats){
  try{
    if(value === undefined){ dsSyncDiagNoteDrop(path, 'undefined', stats); return undefined; }
    if(value === null) return null;
    const t = typeof value;
    if(t === 'string' || t === 'boolean') return value;
    if(t === 'number') return Number.isFinite(value) ? value : null;
    if(t === 'bigint') return String(value);
    if(t === 'function' || t === 'symbol'){ dsSyncDiagNoteDrop(path, t, stats); return undefined; }

    if(t !== 'object') return value;

    try{
      if(typeof window !== 'undefined'){
        if(value === window || value === document){ dsSyncDiagNoteDrop(path, 'window', stats); return undefined; }
        if(typeof Node !== 'undefined' && value instanceof Node){ dsSyncDiagNoteDrop(path, 'dom-node', stats); return undefined; }
        if(typeof Event !== 'undefined' && value instanceof Event){ dsSyncDiagNoteDrop(path, 'event', stats); return undefined; }
      }
    }catch(_){ }

    try{ if(typeof Blob !== 'undefined' && value instanceof Blob){ dsSyncDiagNoteDrop(path, 'blob', stats); return undefined; } }catch(_){ }
    try{ if(typeof File !== 'undefined' && value instanceof File){ dsSyncDiagNoteDrop(path, 'file', stats); return undefined; } }catch(_){ }
    if(value instanceof Date) return value.getTime();
    if(value instanceof RegExp) return String(value);
    if(value instanceof Error) return { name:String(value.name||'Error'), message:String(value.message||'') };
    if(typeof URL !== 'undefined' && value instanceof URL) return String(value);
    if(typeof Map !== 'undefined' && value instanceof Map){
      const obj = {};
      let idx = 0;
      value.forEach(function(v, k){
        const key = String(k);
        const sv = dsSanitizeCloudPayload(v, (path||'root') + '.<map>.' + key, seen, stats);
        if(sv !== undefined) obj[key] = sv;
        idx += 1;
      });
      return obj;
    }
    if(typeof Set !== 'undefined' && value instanceof Set){
      const arr = [];
      let idx = 0;
      value.forEach(function(v){
        const sv = dsSanitizeCloudPayload(v, (path||'root') + '.<set>[' + idx + ']', seen, stats);
        if(sv !== undefined) arr.push(sv);
        idx += 1;
      });
      return arr;
    }
    try{ if(value && typeof value.toMillis === 'function') return Number(value.toMillis()); }catch(_){ }
    try{ if(value && typeof value.seconds === 'number' && typeof value.nanoseconds === 'number'){ return (value.seconds * 1000) + Math.floor((value.nanoseconds||0) / 1000000); } }catch(_){ }

    if(Array.isArray(value)){
      if(seen.has(value)){ dsSyncDiagNoteDrop(path, 'circular-array', stats); return []; }
      seen.add(value);
      const arr = [];
      for(let i=0;i<value.length;i++){
        const sv = dsSanitizeCloudPayload(value[i], (path||'root') + '[' + i + ']', seen, stats);
        if(sv !== undefined) arr.push(sv);
      }
      seen.delete(value);
      return arr;
    }

    const proto = Object.getPrototypeOf(value);
    const plain = !proto || proto === Object.prototype;
    if(!plain){
      try{
        if(value && typeof value.toJSON === 'function'){
          const j = value.toJSON();
          return dsSanitizeCloudPayload(j, (path||'root') + '.toJSON', seen, stats);
        }
      }catch(_){ }
      dsSyncDiagNoteDrop(path, 'non-plain-object', stats);
      return undefined;
    }

    if(seen.has(value)){ dsSyncDiagNoteDrop(path, 'circular-object', stats); return undefined; }
    seen.add(value);
    const out = {};
    Object.keys(value).forEach(function(key){
      const sv = dsSanitizeCloudPayload(value[key], (path ? path + '.' : '') + key, seen, stats);
      if(sv !== undefined) out[key] = sv;
    });
    seen.delete(value);
    return out;
  }catch(_){
    dsSyncDiagNoteDrop(path, 'sanitize-exception', stats);
    return undefined;
  }
}

function dsProjectCloudSafeProposalPayload(payload){
  try{
    const src = (payload && typeof payload === 'object') ? payload : {};
    const customerSrc = (src.customer && typeof src.customer === 'object') ? src.customer : {};
    const petSrc = (src.pet && typeof src.pet === 'object') ? src.pet : {};
    const clean = {
      source: String(src.source || ''),
      mode: String(src.mode || ''),
      customerId: String(src.customerId || customerSrc.customerId || customerSrc.id || ''),
      petId: String(src.petId || petSrc.petId || petSrc.id || petSrc.dogId || ''),
      contractVersion: String(src.contractVersion || ''),
      accepted: !!src.accepted,
      submittedAt: src.submittedAt == null ? null : src.submittedAt,
      customer: {
        id: String(customerSrc.id || customerSrc.customerId || ''),
        customerId: String(customerSrc.customerId || customerSrc.id || ''),
        uid: String(customerSrc.uid || customerSrc.customerUid || customerSrc.portalUid || ''),
        name: String(customerSrc.name || ''),
        email: String(customerSrc.email || ''),
        phone: String(customerSrc.phone || customerSrc.mobile || customerSrc.tel || ''),
        street: String(customerSrc.street || ''),
        zip: String(customerSrc.zip || ''),
        city: String(customerSrc.city || ''),
        emergencyContact: String(customerSrc.emergencyContact || customerSrc.emergencyName || ''),
        emergencyPhone: String(customerSrc.emergencyPhone || ''),
        note: String(customerSrc.note || '')
      },
      pet: {
        id: String(petSrc.id || petSrc.petId || petSrc.dogId || ''),
        petId: String(petSrc.petId || petSrc.id || petSrc.dogId || ''),
        customerId: String(petSrc.customerId || petSrc.ownerId || ''),
        name: String(petSrc.name || ''),
        breed: String(petSrc.breed || ''),
        birth: String(petSrc.birth || petSrc.birthdate || petSrc.birthDate || ''),
        birthdate: String(petSrc.birthdate || petSrc.birthDate || petSrc.birth || ''),
        sex: String(petSrc.sex || ''),
        chip: String(petSrc.chipNumber || petSrc.chip || ''),
        chipNumber: String(petSrc.chipNumber || petSrc.chip || ''),
        insuranceStatus: String(petSrc.insuranceStatus || ''),
        vaccinatedConfirmed: !!petSrc.vaccinatedConfirmed,
        note: String(petSrc.note || '')
      }
    };
    try{ if(!clean.customerId) clean.customerId = clean.customer.customerId || ''; }catch(_){ }
    try{ if(!clean.petId) clean.petId = clean.pet.petId || ''; }catch(_){ }
    return clean;
  }catch(_){ return {}; }
}

function dsNormalizeFirestoreShape(value, path, seen, stats, insideArray){
  try{
    if(value === undefined) return undefined;
    if(value === null) return null;
    const t = typeof value;
    if(t === 'string' || t === 'boolean') return value;
    if(t === 'number') return Number.isFinite(value) ? value : null;
    if(t === 'bigint') return String(value);
    if(t === 'function' || t === 'symbol') return undefined;
    if(t !== 'object') return value;
    try{ if(value instanceof Date) return value.getTime(); }catch(_){ }
    try{ if(value instanceof RegExp) return String(value); }catch(_){ }
    try{ if(value instanceof Error) return { name:String(value.name||'Error'), message:String(value.message||'') }; }catch(_){ }
    try{ if(typeof URL !== 'undefined' && value instanceof URL) return String(value); }catch(_){ }
    try{ if(value && typeof value.toMillis === 'function') return Number(value.toMillis()); }catch(_){ }
    try{ if(value && typeof value.seconds === 'number' && typeof value.nanoseconds === 'number') return (value.seconds * 1000) + Math.floor((value.nanoseconds||0) / 1000000); }catch(_){ }
    try{ if(typeof Blob !== 'undefined' && value instanceof Blob) return undefined; }catch(_){ }
    try{ if(typeof File !== 'undefined' && value instanceof File) return undefined; }catch(_){ }
    if(Array.isArray(value)){
      if(seen && seen.has(value)) return [];
      try{ if(seen) seen.add(value); }catch(_){ }
      const arr = [];
      for(let i=0;i<value.length;i++){
        const itemPath = (path || 'payload') + '[' + i + ']';
        const sv = dsNormalizeFirestoreShape(value[i], itemPath, seen, stats, true);
        if(sv === undefined) continue;
        if(Array.isArray(sv)){
          try{ dsSyncDiagNoteDrop(itemPath, 'nested-array-stringified', stats); }catch(_){ }
          try{ arr.push(JSON.stringify(sv)); }catch(_){ arr.push('[]'); }
        }else{
          arr.push(sv);
        }
      }
      try{ if(seen) seen.delete(value); }catch(_){ }
      return arr;
    }
    const proto = Object.getPrototypeOf(value);
    const plain = !proto || proto === Object.prototype;
    if(!plain){
      try{
        if(value && typeof value.toJSON === 'function'){
          return dsNormalizeFirestoreShape(value.toJSON(), (path || 'payload') + '.toJSON', seen, stats, insideArray);
        }
      }catch(_){ }
      const outLoose = {};
      try{ Object.keys(value).forEach(function(k){ outLoose[k] = value[k]; }); }catch(_){ }
      return dsNormalizeFirestoreShape(outLoose, path, seen, stats, insideArray);
    }
    if(seen && seen.has(value)) return undefined;
    try{ if(seen) seen.add(value); }catch(_){ }
    const out = {};
    Object.keys(value || {}).forEach(function(key){
      const sv = dsNormalizeFirestoreShape(value[key], (path ? path + '.' : '') + key, seen, stats, false);
      if(sv !== undefined) out[key] = sv;
    });
    try{ if(seen) seen.delete(value); }catch(_){ }
    return out;
  }catch(_){
    return undefined;
  }
}

function dsProjectCloudSafeInboxRow(row){
  try{
    const src = (row && typeof row === 'object') ? row : {};
    const out = {};
    [
      'id','proposalId','proposal','taskId','task','title','status','proposalStatus','templateId','formKey','kind','proposalType',
      'customerId','cid','customerUid','customerEmail','customerName','petId','pid','petName','dogId',
      'submittedAt','createdAt','updatedAt','reviewedAt','resolvedAt','ownerId','orgId','rowKey','__rowId','__sourceKey','mirroredFromProposal'
    ].forEach(function(key){
      try{ if(src[key] !== undefined) out[key] = src[key]; }catch(_){ }
    });
    if(src.payloadSubmitted) out.payloadSubmitted = dsProjectCloudSafeProposalPayload(src.payloadSubmitted);
    if(src.payloadDraft) out.payloadDraft = dsProjectCloudSafeProposalPayload(src.payloadDraft);
    if(src.payload) out.payload = dsProjectCloudSafeProposalPayload(src.payload);
    if(src.customer && typeof src.customer === 'object') out.customer = dsProjectCloudSafeProposalPayload({ customer: src.customer }).customer;
    if(src.pet && typeof src.pet === 'object') out.pet = dsProjectCloudSafeProposalPayload({ pet: src.pet }).pet;
    return out;
  }catch(_){ return {}; }
}
function dsPruneProblemSyncFields(root){return root;}

function dsPrepareCloudPayload(src){
  const stats = { droppedCount:0, droppedPaths:[], droppedKinds:{} };
  const sanitized = dsSanitizeCloudPayload(src, 'payload', new WeakSet(), stats) || {};
  const normalized = dsNormalizeFirestoreShape(sanitized, 'payload', new WeakSet(), stats, false) || {};
  const clean = dsPruneProblemSyncFields(normalized);
  return { clean, stats };
}


function dsStrictJsonReplacer(key, value){
  try{
    if(value === undefined) return null;
    const t = typeof value;
    if(t === 'function' || t === 'symbol') return null;
    if(t === 'bigint') return String(value);
    if(t === 'number') return Number.isFinite(value) ? value : null;
    if(value === null) return null;
    if(value instanceof Date) return value.getTime();
    if(value instanceof RegExp) return String(value);
    if(value instanceof Error) return { name:String(value.name||'Error'), message:String(value.message||'') };
    try{ if(typeof URL !== 'undefined' && value instanceof URL) return String(value); }catch(_){ }
    try{ if(typeof Blob !== 'undefined' && value instanceof Blob) return null; }catch(_){ }
    try{ if(typeof File !== 'undefined' && value instanceof File) return null; }catch(_){ }
    try{ if(typeof window !== 'undefined'){ if(value === window || value === document) return null; if(typeof Node !== 'undefined' && value instanceof Node) return null; if(typeof Event !== 'undefined' && value instanceof Event) return null; } }catch(_){ }
    try{ if(value && typeof value.toMillis === 'function') return Number(value.toMillis()); }catch(_){ }
    try{ if(value && typeof value.seconds === 'number' && typeof value.nanoseconds === 'number') return (value.seconds * 1000) + Math.floor((value.nanoseconds||0) / 1000000); }catch(_){ }
    try{ if(typeof Map !== 'undefined' && value instanceof Map) return Object.fromEntries(Array.from(value.entries()).map(function(entry){ return [String(entry[0]), entry[1]]; })); }catch(_){ }
    try{ if(typeof Set !== 'undefined' && value instanceof Set) return Array.from(value.values()); }catch(_){ }
    if(Array.isArray(value)) return value;
    if(value && typeof value === 'object'){
      const proto = Object.getPrototypeOf(value);
      if(proto && proto !== Object.prototype){
        try{ if(typeof value.toJSON === 'function') return value.toJSON(); }catch(_){ }
        const out = {};
        try{ Object.keys(value).forEach(function(k){ out[k] = value[k]; }); }catch(_){ }
        return out;
      }
    }
    return value;
  }catch(_){
    return null;
  }
}
function dsPrepareCloudPayloadStrict(src){
  const stats = { mode:'json-replacer', droppedCount:0, droppedPaths:[], droppedKinds:{} };
  try{
    const json = JSON.stringify(src, dsStrictJsonReplacer);
    const parsed = json ? JSON.parse(json) : {};
    const normalized = dsNormalizeFirestoreShape(parsed, 'payload', new WeakSet(), stats, false) || {};
    const clean = dsPruneProblemSyncFields(normalized);
    return { clean: clean || {}, stats };
  }catch(err){
    stats.error = String((err && err.message) || err || 'unknown');
    return { clean: {}, stats };
  }
}

function dsTracePayloadSections(payload){
  const out = { first:null, sections:[], summary:'' };
  try{
    const root = (payload && typeof payload === 'object') ? payload : {};
    const keys = Object.keys(root || {});
    const seen = new WeakSet();
    function mark(section, path, kind){
      const row = { section:String(section||'payload'), path:String(path||'payload'), kind:String(kind||'invalid') };
      if(!out.first) out.first = row;
      return row;
    }
    function inspect(value, path, section, inArray){
      if(value === undefined) return mark(section, path, 'undefined');
      if(value === null) return null;
      const t = typeof value;
      if(t === 'string' || t === 'boolean') return null;
      if(t === 'number') return Number.isFinite(value) ? null : mark(section, path, 'non-finite-number');
      if(t === 'bigint') return mark(section, path, 'bigint');
      if(t === 'function' || t === 'symbol') return mark(section, path, t);
      if(t !== 'object') return null;
      try{
        if(typeof window !== 'undefined'){
          if(value === window || value === document) return mark(section, path, 'window');
          if(typeof Node !== 'undefined' && value instanceof Node) return mark(section, path, 'dom-node');
          if(typeof Event !== 'undefined' && value instanceof Event) return mark(section, path, 'event');
        }
      }catch(_){ }
      try{ if(typeof Blob !== 'undefined' && value instanceof Blob) return mark(section, path, 'blob'); }catch(_){ }
      try{ if(typeof File !== 'undefined' && value instanceof File) return mark(section, path, 'file'); }catch(_){ }
      if(value instanceof Date || value instanceof RegExp || value instanceof Error) return null;
      try{ if(typeof URL !== 'undefined' && value instanceof URL) return null; }catch(_){ }
      if(Array.isArray(value)){
        if(inArray) return mark(section, path, 'nested-array');
        if(seen.has(value)) return mark(section, path, 'circular-array');
        seen.add(value);
        for(let i=0;i<value.length;i++){
          const fail = inspect(value[i], path + '[' + i + ']', section, true);
          if(fail){ seen.delete(value); return fail; }
        }
        seen.delete(value);
        return null;
      }
      const proto = Object.getPrototypeOf(value);
      const plain = !proto || proto === Object.prototype;
      if(!plain) return mark(section, path, 'non-plain-object');
      if(seen.has(value)) return mark(section, path, 'circular-object');
      seen.add(value);
      const keys2 = Object.keys(value || {});
      for(let i=0;i<keys2.length;i++){
        const k = keys2[i];
        const fail = inspect(value[k], path + '.' + k, section, false);
        if(fail){ seen.delete(value); return fail; }
      }
      seen.delete(value);
      return null;
    }
    keys.forEach(function(key){
      try{
        const fail = inspect(root[key], 'payload.' + key, key, false);
        out.sections.push(fail ? (String(key) + ':FAIL<' + fail.kind + '> @ ' + fail.path) : (String(key) + ':ok'));
      }catch(err){
        out.sections.push(String(key) + ':TRACEERR<' + String((err && err.message) || err || 'unknown') + '>');
        if(!out.first) out.first = { section:String(key), path:'payload.' + String(key), kind:'trace-error' };
      }
    });
    out.summary = out.sections.slice(0,6).join(' | ');
  }catch(err){
    out.first = { section:'payload', path:'payload', kind:'trace-error:' + String((err && err.message) || err || 'unknown') };
    out.summary = 'trace-error';
  }
  return out;
}
try{ window.__dsPayloadTraceDump = function(){ try{ return JSON.stringify(window.__dsPayloadTrace || {}, null, 2); }catch(_){ return ''; } }; }catch(_){ }

async function dsProbeCloudValue(ref, path, value){
  const out = { path:String(path||'payload'), kind:'unknown', message:'', tries:0 };
  try{
    if(!ref || !ref.parent || !ref.id){ out.kind='no-probe-ref'; return out; }
    const probeRef = ref.parent.doc(String(ref.id) + '__diagprobe');
    async function tryWrite(node, wrapArray){
      out.tries += 1;
      if(wrapArray) return await probeRef.set({ probe:[node], probedAt: Date.now() }, { merge:false });
      return await probeRef.set({ probe:node, probedAt: Date.now() }, { merge:false });
    }
    async function walk(node, nodePath, arrayCtx){
      try{
        await tryWrite(node, arrayCtx);
        return null;
      }catch(err){
        const msg = String((err && err.message) || err || 'probe-failed');
        if(node == null){ return { path:nodePath, kind:'nullish', message:msg }; }
        const t = typeof node;
        if(t !== 'object') return { path:nodePath, kind:t, message:msg };
        if(Array.isArray(node)){
          for(let i=0;i<node.length;i++){
            const fail = await walk(node[i], nodePath + '[' + i + ']', true);
            if(fail) return fail;
          }
          return { path:nodePath, kind:'array-combination', message:msg };
        }
        const keys = Object.keys(node || {});
        for(let i=0;i<keys.length;i++){
          const key = keys[i];
          try{
            await tryWrite({ [key]: node[key] }, false);
          }catch(_singleErr){
            const fail = await walk(node[key], nodePath + '.' + key, false);
            if(fail) return fail;
            return { path:nodePath + '.' + key, kind:'object-key-combination', message:String((_singleErr && _singleErr.message) || _singleErr || msg) };
          }
        }
        return { path:nodePath, kind:'object-combination', message:msg };
      }
    }
    const found = await walk(value, String(path||'payload'), false);
    if(found) return found;
    out.kind='no-fail-found';
    return out;
  }catch(err){
    out.kind='probe-exception';
    out.message = String((err && err.message) || err || 'unknown');
    return out;
  }
}
async function dsProbeCloudSuspectSections(ref, payload){
  const root = (payload && typeof payload === 'object') ? payload : {};
  const preferred = ['inboxSubmissions','inboxAssignments','submissions','assignments'];
  const names = [];
  preferred.forEach(function(k){ if(Object.prototype.hasOwnProperty.call(root, k)) names.push(k); });
  if(!names.length){
    Object.keys(root || {}).forEach(function(k){
      if(names.length >= 4) return;
      if(/sub/i.test(k) || /assign/i.test(k)) names.push(k);
    });
  }
  const results = [];
  for(let i=0;i<names.length;i++){
    const name = names[i];
    try{
      const res = await dsProbeCloudValue(ref, 'payload.' + name, root[name]);
      results.push({ section:name, path:String((res && res.path) || ('payload.' + name)), kind:String((res && res.kind) || 'unknown'), message:String((res && res.message) || ''), tries:Number((res && res.tries) || 0) });
      if(res && res.kind && res.kind !== 'no-fail-found') break;
    }catch(err){
      results.push({ section:name, path:'payload.' + name, kind:'probe-crash', message:String((err && err.message) || err || 'unknown'), tries:0 });
      break;
    }
  }
  try{ window.__dsProbeResults = results; }catch(_){ }
  return results;
}
