function withTimeout(promise, ms){
  return new Promise((resolve, reject)=>{
    const t = setTimeout(()=>reject(new Error("timeout")), ms);
    Promise.resolve(promise).then((v)=>{ clearTimeout(t); resolve(v); }).catch((e)=>{ clearTimeout(t); reject(e); });
  });
}
async function checkCloudReachability(reason){
  const navOnline = dsNavigatorOnline();
  const netOnline = dsEffectiveNetOnline();
  const recentOk = dsHasRecentCloudOk(30*60*1000);
  SYNC.cloudReachCheckedAt = Date.now();
  SYNC.cloudReachError = "";
  if(!cloudIsEnabled() || !CLOUD || !CLOUD.enabled || !CLOUD.db){
    SYNC.cloudReachable = recentOk;
    SYNC.cloudReachError = recentOk ? "" : "Cloud nicht bereit";
    return !!SYNC.cloudReachable;
  }
  if(!CLOUD.user){
    SYNC.cloudReachable = recentOk;
    SYNC.cloudReachError = recentOk ? "" : "nicht angemeldet";
    return !!SYNC.cloudReachable;
  }
  const ref = (typeof cloudStateRef === 'function') ? cloudStateRef() : null;
  if(!ref || !ref.get){
    SYNC.cloudReachable = recentOk;
    SYNC.cloudReachError = recentOk ? "" : "State-Ref fehlt";
    return !!SYNC.cloudReachable;
  }
  try{
    const p = ref.get({ source: 'server' });
    await withTimeout(p, 4000);
    SYNC.cloudReachable = true;
    SYNC.cloudReachError = "";
    try{ window.__dsForcedOnlineUntil = Date.now() + (10*60*1000); }catch(_){ }
    return true;
  }catch(err){
    const code = (err && (err.code || err.name)) ? String(err.code || err.name) : "";
    if(code.includes("permission") || code.includes("PERMISSION")){
      SYNC.cloudReachable = true;
      SYNC.cloudReachError = "keine Rechte";
      return true;
    }
    const softOffline = recentOk || (!!CLOUD.user && (!!netOnline || !!navOnline));
    if(softOffline){
      SYNC.cloudReachable = true;
      SYNC.cloudReachError = "";
      return true;
    }
    SYNC.cloudReachable = false;
    SYNC.cloudReachError = (!navOnline && !code) ? "Browser meldet offline" : (code || "nicht erreichbar");
    return false;
  }
}
let _cloudPingTimer = null;
function scheduleCloudPing(delayMs=0, reason=""){
  try{
    if(_cloudPingTimer) clearTimeout(_cloudPingTimer);
    _cloudPingTimer = setTimeout(async ()=>{
      await checkCloudReachability(reason);
      updateSyncUI();
    }, Math.max(0, delayMs));
  }catch(e){}
}
function ds215StabilizeContractSync(reason="contract-open"){
  try{
    if(ds216SoftKeepContractOnline(reason + '-soft')) return true;
    const resolvedUser = (typeof getCloudUserResolved === 'function') ? getCloudUserResolved() : null;
    if(!(resolvedUser || ds217LocalUserHint())) return false;
    const now = Date.now();
    const recentOk = dsHasRecentCloudOk(12*60*60*1000);
    if(recentOk || SYNC.cloudReachable || SYNC.cloudLastOkAt || SYNC.cloudLastSeenAt){
      SYNC.cloudReachable = true;
      SYNC.cloudReachError = '';
      SYNC.cloudReachCheckedAt = now;
      SYNC.cloudLastSeenAt = Math.max(Number(SYNC.cloudLastSeenAt||0), Number(SYNC.cloudLastOkAt||0), now);
      if(!SYNC.cloudLastOkAt) SYNC.cloudLastOkAt = now;
      window.__dsForcedOnlineUntil = Math.max(Number(window.__dsForcedOnlineUntil||0), now + (15*60*1000));
      if(SYNC.cloudLastError && (recentOk || SYNC.cloudLastOkAt)) SYNC.cloudLastError = '';
      try{ updateSyncUI(); }catch(_){ }
      try{ if(!SYNC.cloudPending) scheduleCloudPing(450, reason); }catch(_){ }
      return true;
    }
  }catch(_){ }
  return false;
}
