function dsBuildProposalReviewFieldwisePatch(row, customer, pet, baseState){
  const normId = function(v){ try{ return norm(v || ''); }catch(_){ return String(v == null ? '' : v).trim(); } };
  const customerId = normId((customer && (customer.id || customer.customerId)) || (row && (row.customerId || row.cid || row.__targetCustomerId)) || '');
  const petId = normId((pet && (pet.id || pet.petId)) || (row && (row.petId || row.pid || row.__targetPetId)) || '');
  const customerSrc = dsSanitizeReviewFlatBase(customer || {});
  const petSrc = dsSanitizeReviewFlatBase(pet || {});
  const pick = function(src, keys){
    const out = {};
    try{
      (keys || []).forEach(function(key){
        try{
          if(!src || !Object.prototype.hasOwnProperty.call(src, key)) return;
          const v = src[key];
          if(v === undefined) return;
          out[key] = v;
        }catch(_){ }
      });
    }catch(_){ }
    return out;
  };
  const patch = { customerRecords:{}, petRecords:{}, dogRecords:{}, _legacy:{ dogIdToPetId:{}, dogIdToCustomerId:{} } };
  if(customerId){
    const customerCore = pick(customerSrc, ['id','customerId','name','email','phone']);
    customerCore.id = customerId;
    customerCore.customerId = customerId;
    patch.customerRecords[customerId] = customerCore;
  }
  if(petId){
    const petCore = pick(petSrc, ['id','petId','customerId','name','breed','birthdate','sex','chip','chipNumber']);
    petCore.id = petId;
    petCore.petId = petId;
    if(customerId && !petCore.customerId) petCore.customerId = customerId;
    patch.petRecords[petId] = petCore;
  }
  let dogId = '';
  try{ dogId = (typeof getLegacyDogIdForPet === 'function') ? String(getLegacyDogIdForPet(petId) || '') : ''; }catch(_){ dogId = ''; }
  const legacySource = (baseState && baseState._legacy && typeof baseState._legacy === 'object') ? baseState._legacy : ((state && state._legacy && typeof state._legacy === 'object') ? state._legacy : {});
  try{
    const src1 = (legacySource && legacySource.dogIdToPetId && typeof legacySource.dogIdToPetId === 'object') ? legacySource.dogIdToPetId : {};
    Object.keys(src1).forEach(function(key){ try{ const k = String(key||'').trim(); const v = String(src1[key] == null ? '' : src1[key]).trim(); if(k && v) patch._legacy.dogIdToPetId[k] = v; }catch(_){ } });
    const src2 = (legacySource && legacySource.dogIdToCustomerId && typeof legacySource.dogIdToCustomerId === 'object') ? legacySource.dogIdToCustomerId : {};
    Object.keys(src2).forEach(function(key){ try{ const k = String(key||'').trim(); const v = String(src2[key] == null ? '' : src2[key]).trim(); if(k && v) patch._legacy.dogIdToCustomerId[k] = v; }catch(_){ } });
  }catch(_){ }
  if(!dogId && petId){
    try{ Object.keys(patch._legacy.dogIdToPetId || {}).some(function(did){ if(normId(patch._legacy.dogIdToPetId[did]) === petId){ dogId = String(did || ''); return true; } return false; }); }catch(_){ }
  }
  if(dogId){
    patch._legacy.dogIdToPetId[dogId] = petId;
    if(customerId) patch._legacy.dogIdToCustomerId[dogId] = customerId;
    patch.dogRecords[dogId] = {
      id: dogId,
      name: String((petSrc && petSrc.name) || ''),
      owner: String((customerSrc && customerSrc.name) || ''),
      phone: String((customerSrc && customerSrc.phone) || '')
    };
  }
  try{ patch.schemaVersion = Math.max(Number((state && state.schemaVersion) || (baseState && baseState.schemaVersion) || 2) || 2, 2); }catch(_){ patch.schemaVersion = 2; }
  patch._cloudUpdatedAt = Date.now();
  patch._localUpdatedAt = patch._cloudUpdatedAt;
  return patch;
}

async function dsForceProposalPersistFieldwiseReviewRow(row, customer, pet, reason){
  const tag = String(reason || 'proposal-adopt-fieldwise').trim() || 'proposal-adopt-fieldwise';
  if(!(CLOUD && CLOUD.enabled && CLOUD.user)) return { ok:true, skipped:true, reason:tag };
  const ref = cloudStateRef();
  if(!ref) return { ok:true, skipped:true, reason:tag, noRef:true };
  let remote = null;
  try{
    const loaded = await cloudLoadStateWithRetry(2);
    remote = (loaded && typeof loaded === 'object' && Object.prototype.hasOwnProperty.call(loaded, 'remote')) ? (loaded.remote || null) : (loaded || null);
  }catch(_){ remote = null; }
  const patch = dsBuildProposalReviewFieldwisePatch(row, customer, pet, (remote && typeof remote === 'object') ? remote : {});
  const stamp = Date.now();
  const stages = [];
  const writeStage = async function(name, obj){
    if(!obj || typeof obj !== 'object' || !Object.keys(obj).length){ stages.push(name + ':skip'); return; }
    await ref.set({ payload: obj, updatedAt: stamp, updatedBy: CLOUD.user.email || CLOUD.user.uid }, { merge:true });
    stages.push(name + ':ok');
  };
  try{
    if(patch.customerRecords && Object.keys(patch.customerRecords).length){
      await writeStage('customer', { customerRecords: patch.customerRecords, schemaVersion: patch.schemaVersion, _cloudUpdatedAt: stamp, _localUpdatedAt: stamp });
    }else{ stages.push('customer:skip'); }
    if(patch.petRecords && Object.keys(patch.petRecords).length){
      await writeStage('pet', { petRecords: patch.petRecords, schemaVersion: patch.schemaVersion, _cloudUpdatedAt: stamp, _localUpdatedAt: stamp });
    }else{ stages.push('pet:skip'); }
    if(patch.dogRecords && Object.keys(patch.dogRecords).length){
      await writeStage('dog', { dogRecords: patch.dogRecords, schemaVersion: patch.schemaVersion, _cloudUpdatedAt: stamp, _localUpdatedAt: stamp });
    }else{ stages.push('dog:skip'); }
    if(patch._legacy && ((patch._legacy.dogIdToPetId && Object.keys(patch._legacy.dogIdToPetId).length) || (patch._legacy.dogIdToCustomerId && Object.keys(patch._legacy.dogIdToCustomerId).length))){
      await writeStage('legacy', { _legacy: patch._legacy, schemaVersion: patch.schemaVersion, _cloudUpdatedAt: stamp, _localUpdatedAt: stamp });
    }else{ stages.push('legacy:skip'); }
  }catch(err){
    try{ dsSetProposalOpenDiag('save-fieldwise-fail pet=' + String((pet && (pet.id || pet.petId)) || '--') + ' customer=' + String((customer && (customer.id || customer.customerId)) || '--') + ' stage=' + String(stages.join('|') || '--') + ' msg=' + String((err && err.message) || err || 'unknown'), true); }catch(_){ }
    throw err;
  }
  try{ CLOUD.lastPushOkAt = stamp; CLOUD.lastPushError = ''; }catch(_){ }
  try{ SYNC.cloudLastOkAt = stamp; SYNC.cloudLastError = ''; SYNC.cloudPending = false; }catch(_){ }
  try{ dsSetSyncDiag('proposalPersist:fieldwise-ok reason=' + tag + ' stages=' + stages.join('|') + ' · ' + dsSyncDiagStateSummary(), false); }catch(_){ }
  try{ dsSetProposalOpenDiag('save-fieldwise-ok pet=' + String((pet && (pet.id || pet.petId)) || '--') + ' customer=' + String((customer && (customer.id || customer.customerId)) || '--') + ' stage=' + stages.join('|'), false); }catch(_){ }
  try{ dsClearSyncDiag(); }catch(_){ }
  try{ updateSyncUI(); }catch(_){ }
  return { ok:true, skipped:false, reason:tag, fieldwise:true, stages:stages.slice() };
}
try{ window.dsForceProposalPersistFieldwiseReviewRow = dsForceProposalPersistFieldwiseReviewRow; }catch(_){ }

function dsBuildReviewSubsetPersistPayload(kind, opts){
  try{
    const mode = String(kind || '').trim().toLowerCase();
    const options = (opts && typeof opts === 'object') ? opts : {};
    const stamp = Date.now();
    let payload = {
      schemaVersion: Math.max(Number((state && state.schemaVersion) || 2) || 2, 2),
      _cloudUpdatedAt: stamp,
      _localUpdatedAt: stamp
    };
    if(mode === 'stay'){
      const doc = (options.doc && typeof options.doc === 'object') ? options.doc : null;
      const docId = String((options.docId || (doc && doc.id) || '') || '').trim();
      if(doc && docId){
        let prepared = {};
        try{
          prepared = dsPrepareCloudPayloadStrict({ docRecords:{ [docId]: doc } });
        }catch(_){ prepared = {}; }
        const cleanRoot = (prepared && prepared.clean && typeof prepared.clean === 'object') ? prepared.clean : {};
        const cleanMap = (cleanRoot.docRecords && typeof cleanRoot.docRecords === 'object') ? cleanRoot.docRecords : {};
        const cleanDoc = cleanMap[docId];
        if(cleanDoc && typeof cleanDoc === 'object'){
          payload.docRecords = { [docId]: cleanDoc };
        }
      }
    }
    if(mode === 'contract'){
      const sigKey = String((options.signatureKey || '') || '').trim();
      const agrKey = String((options.agreementKey || '') || '').trim();
      const sigRec = options.signatureRec && typeof options.signatureRec === 'object' ? options.signatureRec : null;
      const agrRec = options.agreementRec && typeof options.agreementRec === 'object' ? options.agreementRec : null;
      if(sigKey && sigRec){
        let preparedSig = {};
        try{ preparedSig = dsPrepareCloudPayloadStrict({ contractSignatures:{ [sigKey]: sigRec } }); }catch(_){ preparedSig = {}; }
        const cleanSigRoot = (preparedSig && preparedSig.clean && typeof preparedSig.clean === 'object') ? preparedSig.clean : {};
        if(cleanSigRoot.contractSignatures && typeof cleanSigRoot.contractSignatures === 'object' && cleanSigRoot.contractSignatures[sigKey]){
          payload.contractSignatures = { [sigKey]: cleanSigRoot.contractSignatures[sigKey] };
        }
      }
      if(agrKey && agrRec){
        let preparedAgr = {};
        try{ preparedAgr = dsPrepareCloudPayloadStrict({ contractAgreements:{ [agrKey]: agrRec } }); }catch(_){ preparedAgr = {}; }
        const cleanAgrRoot = (preparedAgr && preparedAgr.clean && typeof preparedAgr.clean === 'object') ? preparedAgr.clean : {};
        if(cleanAgrRoot.contractAgreements && typeof cleanAgrRoot.contractAgreements === 'object' && cleanAgrRoot.contractAgreements[agrKey]){
          payload.contractAgreements = { [agrKey]: cleanAgrRoot.contractAgreements[agrKey] };
        }
      }
    }
    return payload;
  }catch(_){ return { schemaVersion:2, _cloudUpdatedAt:Date.now(), _localUpdatedAt:Date.now() }; }
}
async function dsForceReviewSubsetPersist(kind, opts){
  const mode = String(kind || '').trim().toLowerCase();
  const options = (opts && typeof opts === 'object') ? opts : {};
  const tag = String(options.reason || ('review-subset-' + (mode || 'unknown'))).trim() || ('review-subset-' + (mode || 'unknown'));
  if(!(CLOUD && CLOUD.enabled && CLOUD.user)) return { ok:true, skipped:true, reason:tag };
  const ref = cloudStateRef();
  if(!ref) return { ok:true, skipped:true, reason:tag, noRef:true };
  const stamp = Date.now();
  const stages = [];
  try{
    if((mode === 'stay' || mode === 'contract') && typeof dsForceProposalPersistFieldwiseReviewRow === 'function'){
      try{
        const row = options.row || null;
        const customer = options.customer || null;
        const pet = options.pet || null;
        await dsForceProposalPersistFieldwiseReviewRow(row, customer, pet, tag + '-fieldwise');
        stages.push('fieldwise:ok');
      }catch(fieldErr){
        stages.push('fieldwise:fail');
        try{ dsSetProposalOpenDiag('save-review-subset-fieldwise-fail kind=' + String(mode || '--') + ' msg=' + String((fieldErr && fieldErr.message) || fieldErr || 'unknown'), true); }catch(_){ }
      }
    }
    const payload = dsBuildReviewSubsetPersistPayload(mode, options);
    const hasPayload = !!(payload && typeof payload === 'object' && (
      (payload.docRecords && Object.keys(payload.docRecords).length) ||
      (payload.contractSignatures && Object.keys(payload.contractSignatures).length) ||
      (payload.contractAgreements && Object.keys(payload.contractAgreements).length)
    ));
    if(!hasPayload){
      stages.push('subset:skip');
      return { ok:true, skipped:true, reason:tag, stages:stages.slice() };
    }
    await ref.set({ payload, updatedAt: stamp, updatedBy: CLOUD.user.email || CLOUD.user.uid }, { merge:true });
    stages.push('subset:ok');
  }catch(err){
    try{ dsSetProposalOpenDiag('save-review-subset-fail kind=' + String(mode || '--') + ' stage=' + String(stages.join('|') || '--') + ' msg=' + String((err && err.message) || err || 'unknown'), true); }catch(_){ }
    throw err;
  }
  try{ CLOUD.lastPushOkAt = stamp; CLOUD.lastPushError = ''; }catch(_){ }
  try{ SYNC.cloudLastOkAt = stamp; SYNC.cloudLastError = ''; SYNC.cloudPending = false; }catch(_){ }
  try{ dsSetSyncDiag('reviewSubsetPersist:ok reason=' + tag + ' kind=' + mode + ' stage=' + stages.join('|') + ' · ' + dsSyncDiagStateSummary(), false); }catch(_){ }
  try{ dsSetProposalOpenDiag('save-review-subset-ok kind=' + String(mode || '--') + ' stage=' + stages.join('|'), false); }catch(_){ }
  try{ dsClearSyncDiag(); }catch(_){ }
  try{ updateSyncUI(); }catch(_){ }
  return { ok:true, skipped:false, reason:tag, stages:stages.slice(), subset:true };
}
try{ window.dsForceReviewSubsetPersist = dsForceReviewSubsetPersist; }catch(_){ }

/* ===== Rollen, Kundenportal & Aufgaben (Weg A) ===== */
function hideStaffUIForCustomer(){
  // Tabs / Panels umschalten
  try{
    const tabs = $$('.tabs .tab');
    tabs.forEach(btn=>{
      const t = btn.dataset.tab;
      if(t === 'customerPortal'){
        btn.style.display = 'none';
      } else {
        btn.style.display = 'none';
      }
    });
    const nav = document.querySelector('nav.tabs');
    if(nav) nav.style.display = 'none';
  }catch(_){ }
  try{
    // alle Panels verstecken außer customerPortal
    $$('.panel').forEach(p=>{ p.classList.remove('is-active'); p.style.display = 'none'; });
    const cp = document.getElementById('customerPortal');
    if(cp){ cp.style.display = ''; cp.classList.add('is-active'); }
  }catch(_){ }
}
function showStaffUI(){
  try{
    if(isCustomerMainMode()) return;
    const nav = document.querySelector('nav.tabs');
    if(nav) nav.style.display = '';
    $$('.panel').forEach(p=>{ p.style.display = ''; });
    const cp = document.getElementById('customerPortal');
    if(cp){ cp.style.display = 'none'; cp.classList.remove('is-active'); }
  }catch(_){ }
  // Inbox nur für staff/admin
  try{
    const tabInbox = document.getElementById('tabInbox');
    if(tabInbox) tabInbox.style.display = isStaff() ? '' : 'none';
  }catch(_){ }
  // Kalender nur für staff/admin
  try{
    const tabCal = document.getElementById('tabCalendar');
    if(tabCal) tabCal.style.display = isStaff() ? '' : 'none';
  }catch(_){ }
}

function dsGetCustomerMainHandoff(){
  try{
    const raw = String(sessionStorage.getItem('ds_customer_main_handoff') || '').trim();
    if(!raw) return null;
    const parsed = JSON.parse(raw);
    if(!parsed || typeof parsed !== 'object') return null;
    const auth = (parsed.auth && typeof parsed.auth === 'object') ? parsed.auth : {};
    const customer = (parsed.customer && typeof parsed.customer === 'object') ? parsed.customer : {};
    const pets = Array.isArray(parsed.pets) ? parsed.pets.filter(Boolean) : [];
    const mode = String(parsed.mode || sessionStorage.getItem('ds_customer_main_mode') || '').trim().toLowerCase();
    return { mode, auth, customer, pets, ts: Number(parsed.ts || 0) || 0 };
  }catch(_){ return null; }
}
function getCustomerMainMode(){
  try{
    const p = (location && location.pathname) ? location.pathname.toLowerCase() : '';
    if(!((p.endsWith('/app.html') || p.endsWith('app.html')))) return '';
    const qs = new URLSearchParams((location && location.search) ? location.search : '');
    const forced = String(qs.get('customer_mode') || '').trim().toLowerCase();
    if(['dogs','contract','stay'].includes(forced)) return forced;
    const bodyMode = String((document.body && document.body.dataset && document.body.dataset.customerMode) || '').trim().toLowerCase();
    if(['dogs','contract','stay'].includes(bodyMode)) return bodyMode;
    const ssMode = String((sessionStorage.getItem('ds_customer_main_mode') || window.__dsCustomerMainModeActive || '')).trim().toLowerCase();
    const handoff = (typeof dsGetCustomerMainHandoff === 'function') ? dsGetCustomerMainHandoff() : null;
    const allow = (typeof dsCustomerMainArtifactsMatchUser === 'function') ? !!dsCustomerMainArtifactsMatchUser() : false;
    if(allow && ['dogs','contract','stay'].includes(ssMode)) return ssMode;
    const handoffMode = String((handoff && handoff.mode) || '').trim().toLowerCase();
    if(allow && ['dogs','contract','stay'].includes(handoffMode)) return handoffMode;
    return '';
  }catch(_){ return ''; }
}
function isCustomerMainMode(mode){
  try{
    const current = getCustomerMainMode();
    return mode ? current === String(mode||'') : !!current;
  }catch(_){ return false; }
}
function isCustomerMainDogsMode(){
  try{ return isCustomerMainMode('dogs'); }catch(_){ return false; }
}
function getCustomerMainModeLoose(){
  try{
    const strict = getCustomerMainMode();
    if(strict) return strict;
    const p = (location && location.pathname) ? location.pathname.toLowerCase() : '';
    if(!((p.endsWith('/app.html') || p.endsWith('app.html')))) return '';
    const ss = String((sessionStorage.getItem('ds_customer_main_mode') || window.__dsCustomerMainModeActive || '')).trim().toLowerCase();
    if(!['dogs','contract','stay'].includes(ss)) return '';
    const allow = (typeof dsCustomerMainArtifactsMatchUser === 'function') ? dsCustomerMainArtifactsMatchUser() : false;
    if(!allow) return '';
    return ss;
  }catch(_){ return ''; }
}
function isCustomerMainModeLoose(mode){
  try{
    const current = getCustomerMainModeLoose();
    return mode ? current === String(mode||'') : !!current;
  }catch(_){ return false; }
}
function dsGetCustomerAuthProfile(){const u=firebase.auth().currentUser;return u?{uid:u.uid,email:String(u.email||'').toLowerCase(),displayName:u.displayName||'',handoffCustomer:DSWorkflow.context().customer,handoffPets:DSWorkflow.context().pets}:{};}
function dsBuildCustomerShadow(existing){
  try{
    const auth = dsGetCustomerAuthProfile();
    const handoffCustomer = (auth && auth.handoffCustomer && typeof auth.handoffCustomer === 'object') ? auth.handoffCustomer : {};
    const raw = { ...((existing && typeof existing === 'object') ? existing : {}), ...(auth.activeCustomerMain ? handoffCustomer : {}) };
    const id = String(raw.id || raw.customerId || raw.portalUid || raw.customerUid || auth.uid || auth.email || '').trim();
    if(!id && !auth.email && !auth.uid) return null;
    return {
      ...(raw||{}),
      id: id || ('shadow:' + String(auth.uid || auth.email || 'customer')),
      customerId: String(raw.customerId || raw.id || id || ('shadow:' + String(auth.uid || auth.email || 'customer'))).trim(),
      name: String(raw.name || raw.displayName || raw.fullName || auth.displayName || auth.email || 'Kunde').trim(),
      email: String(raw.email || auth.email || '').trim().toLowerCase(),
      phone: String(raw.phone || auth.phone || '').trim(),
      portalUid: String(raw.portalUid || raw.customerUid || raw.uid || auth.uid || '').trim(),
      customerUid: String(raw.customerUid || raw.portalUid || raw.uid || auth.uid || '').trim(),
      __customerShadow: !existing
    };
  }catch(_){ return null; }
}


function dsIsCustomerScopedSession(){
  try{
    const role = String((window.CLOUD && CLOUD.role) || '').trim().toLowerCase();
    if(role !== 'customer') return false;
    const p = String((location && location.pathname) || '').toLowerCase();
    const inKnownCustomerSurface = (p.endsWith('/app.html') || p.endsWith('app.html') || p.endsWith('/customer.html') || p.endsWith('customer.html'));
    if(!inKnownCustomerSurface) return false;
    const auth = (typeof dsGetCustomerAuthProfile === 'function') ? dsGetCustomerAuthProfile() : { email:'', uid:'' };
    const hasPortalDom = !!document.getElementById('customerPortal');
    const hasMode = !!(typeof getCustomerMainModeLoose === 'function' ? getCustomerMainModeLoose() : '') || !!sessionStorage.getItem('ds_customer_main_mode') || !!sessionStorage.getItem('ds_customer_main_handoff');
    const hasAuthMarkers = !!String((auth && auth.email) || '').trim() || !!String((auth && auth.uid) || '').trim() || !!sessionStorage.getItem('ds_customer_auth_handoff_email') || !!sessionStorage.getItem('ds_customer_auth_handoff_uid');
    return !!(hasPortalDom || hasMode || hasAuthMarkers);
  }catch(_){ return false; }
}

function dsGetStrictCustomerMainHandoffContext(){return DSWorkflow.context();}
function dsRenderCustomerModeDebug(ctx){
  try{
    if(!(typeof getCustomerMainModeLoose === 'function' ? getCustomerMainModeLoose() : '')) return;
    const payload = (typeof dsGetCustomerMainHandoff === 'function') ? dsGetCustomerMainHandoff() : null;
    const handoffEmail = String((payload && payload.auth && payload.auth.email) || sessionStorage.getItem('ds_customer_auth_handoff_email') || '').trim().toLowerCase();
    const handoffUid = String((payload && payload.auth && payload.auth.uid) || sessionStorage.getItem('ds_customer_auth_handoff_uid') || '').trim();
    const handoffName = String((payload && payload.customer && (payload.customer.name || payload.customer.email)) || '').trim();
    const resolvedId = String((ctx && ctx.customerId) || '').trim();
    const resolvedName = String((ctx && ctx.customer && (ctx.customer.name || ctx.customer.email)) || '').trim();
    let el = document.getElementById('customerModeDebugLine');
    if(!el){
      el = document.createElement('div');
      el.id = 'customerModeDebugLine';
      el.style.cssText = 'margin:8px 0 10px 0;padding:8px 10px;border-radius:10px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.10);font-size:12px;line-height:1.45;color:#d9d9e3;word-break:break-word;';
    }
    el.textContent = 'Kundenmodus-DIAG · Handoff=' + (handoffName || '—') + ' · Email=' + (handoffEmail || '—') + ' · UID=' + (handoffUid || '—') + ' · Kunde=' + (resolvedName || '—') + ' · customerId=' + (resolvedId || '—');
    const dogsPanel = document.getElementById('dogs');
    const contractPanel = document.getElementById('contract');
    const docsPanel = document.getElementById('documents');
    const activePanel = (dogsPanel && dogsPanel.style.display !== 'none' && dogsPanel) || (contractPanel && contractPanel.style.display !== 'none' && contractPanel) || docsPanel || dogsPanel || contractPanel;
    if(activePanel && !el.parentNode){ activePanel.insertBefore(el, activePanel.firstChild); }
  }catch(_){ }
}

