function enforceCustomerMainCustomerModeUI(){
  const mode = getCustomerMainMode() || 'dogs';
  const targetTab = (mode === 'dogs') ? 'dogs' : ((mode === 'contract') ? 'contract' : 'documents');
  const allowEditorPanel = (mode === 'stay');
  try{ document.body.dataset.customerMode = mode; }catch(_){ }
  try{ sessionStorage.setItem('ds_customer_main_mode', mode); }catch(_){ }
  try{ showAuthGate(false); }catch(_){ }
  try{
    const startPaw = document.querySelector('.paw-start');
    if(startPaw){
      startPaw.style.display = '';
      startPaw.disabled = false;
      startPaw.style.pointerEvents = 'auto';
      startPaw.setAttribute('aria-hidden','false');
      startPaw.onclick = function(ev){ try{ ev.preventDefault(); ev.stopPropagation(); }catch(_){ } try{ location.href = 'customer.html'; }catch(_){ } return false; };
    }
  }catch(_){ }
  try{ const nav = document.querySelector('nav.tabs'); if(nav) nav.style.display = ''; }catch(_){ }
  try{ document.querySelectorAll('.tab').forEach(btn=>{
    const t = String(btn.dataset.tab || '');
    const allow = (t === targetTab || t === 'home');
    btn.style.display = allow ? '' : 'none';
    btn.disabled = !allow;
    btn.style.pointerEvents = allow ? 'auto' : 'none';
    btn.setAttribute('aria-hidden', allow ? 'false' : 'true');
  }); }catch(_){ }
  try{ const top = document.getElementById('btnLogoutTop'); if(top) top.style.display = 'inline-flex'; }catch(_){ }
  try{ const app = document.getElementById('btnLogoutApp'); if(app) app.style.display = 'inline-block'; }catch(_){ }
  try{ const userEl = document.getElementById('syncUser'); if(userEl) userEl.style.display = 'none'; }catch(_){ }
  try{ const btnAddDog = document.getElementById('btnAddDog'); if(btnAddDog){ btnAddDog.style.display = (mode === 'dogs' ? 'none' : btnAddDog.style.display); btnAddDog.disabled = (mode === 'dogs'); } }catch(_){ }
  try{ document.querySelectorAll('.panel').forEach(p=>{ const keep = (p.id === targetTab) || (allowEditorPanel && p.id === 'editor'); p.style.display = keep ? '' : 'none'; p.classList.toggle('is-active', keep); }); }catch(_){ }
  try{ document.querySelectorAll('#quickActions .btn, .start-actions .btn, .panel .btn[data-tab], .hero-card, .glass-card, .quick-card').forEach(el=>{ if(!el.closest('#' + targetTab)) el.style.display = 'none'; }); }catch(_){ }
  try{ if(typeof selectTab === 'function') selectTab(targetTab); }catch(_){ }
}
function enforceCustomerMainDogsUI(){ try{ enforceCustomerMainCustomerModeUI(); }catch(_){ } }

function dsCustomerForceMode(mode){
  try{
    const want = String(mode||'').trim().toLowerCase();
    const bodyMode = String((document.body && document.body.dataset && document.body.dataset.customerMode) || '').trim().toLowerCase();
    const winMode = String((window.__dsCustomerMainModeActive || '')).trim().toLowerCase();
    const forceContract = !!window.__dsForceCustomerContractProposal;
    const forceStay = !!window.__dsForceCustomerStayProposal;
    const ssMode = String((sessionStorage.getItem('ds_customer_main_mode') || '')).trim().toLowerCase();
    const qMode = String((new URLSearchParams(String(location.search||'')).get('customer_mode') || '')).trim().toLowerCase();
    if(want === 'contract') return forceContract || bodyMode === 'contract' || winMode === 'contract' || ssMode === 'contract' || qMode === 'contract';
    if(want === 'stay') return forceStay || bodyMode === 'stay' || winMode === 'stay' || ssMode === 'stay' || qMode === 'stay';
    return !!(bodyMode || winMode || ssMode || qMode || forceContract || forceStay);
  }catch(_){ return false; }
}

async function submitCustomerContractProposalMain(){return DSWorkflow.submitContract();}

async function submitCustomerStayProposalMain(){
    try{
      const ctx=DSWorkflow.context();if(!ctx.verified)throw new Error('Konto noch nicht zugeordnet.');
      syncStayEditorInputsToDoc();
      const dogId=String(currentDoc?.dogId||currentDoc?.petId||'');
      const pet=ctx.pets.find(p=>p.id===dogId || p.dogId===dogId);
      if(!pet)throw new Error('Bitte einen eigenen Hund auswählen.');
      const fields=JSON.parse(JSON.stringify(currentDoc?.fields||{})),meta=JSON.parse(JSON.stringify(currentDoc?.meta||{}));
      for(const target of [fields,meta]){delete target.customerId;delete target.petId;delete target.dogId;}
      Object.assign(meta,{customerId:ctx.customerId,petId:pet.id,dogId:pet.id});
      const signature=typeof ds212ExtractSignature==='function'?ds212ExtractSignature(currentDoc||{}):(currentDoc?.signature||null);
      const id=currentDoc._pendingProposalId || (currentDoc._pendingProposalId=crypto.randomUUID());
      const res=await DSWorkflow.submit({id,templateId:'hundeannahme',title:'Aufenthaltsanfrage',customerId:ctx.customerId,petId:pet.id,
        payloadSubmitted:{staySchemaVersion:1,consentTexts:DSCustomerPortal.consentTexts(),customerId:ctx.customerId,petId:pet.id,meta,fields,signature:signature||null}});
      if(!res.ok)throw res.error;
      alert('An Eingänge übermittelt. Freigabe durch den Administrator ausstehend.');location.replace('customer.html?view=stay');return res;
    }catch(err){alert('Aufenthalt nicht übermittelt: '+err.message);return {ok:false,error:err};}
  }

function prepareCustomerContractMode(){
    window.__dsCustomerContractSubmitHook=submitCustomerContractProposalMain;window.__dsForceCustomerContractProposal=true;
    const ctx=DSWorkflow.context(),cs=document.getElementById('contractCustomerSelect'),ps=document.getElementById('contractPetSelect');
    const selected=ps?.value;renderContractPanel();
    if(cs){cs.replaceChildren(new Option(ctx.customer?.name||'Konto nicht zugeordnet',ctx.customerId));cs.value=ctx.customerId;cs.disabled=true;}
    if(ps){ps.replaceChildren(...ctx.pets.map(p=>new Option(p.name||p.id,p.id)));if(ctx.pets.some(p=>p.id===selected))ps.value=selected;ps.disabled=!ctx.verified;ps.style.pointerEvents='';}
    const admin=document.getElementById('contractAdminBox');if(admin)admin.style.display='none';
    DSWorkflow.renderContractStatus();
  }

