function initCustomerMainDogsMode(){
  try{
    try{ cpWaitForFirebaseUser(10000).then(function(u){ try{ if(u){ window.CLOUD = window.CLOUD || {}; CLOUD.user = u; if(!CLOUD.orgId) CLOUD.orgId = dsResolveCloudOrgId(); } }catch(_){ } }).catch(function(){}); }catch(_){ }
    enforceCustomerMainCustomerModeUI();
    const mode = getCustomerMainModeLoose() || getCustomerMainMode() || 'dogs';
    try{ window.__dsCustomerMainModeActive = mode; }catch(_){ }
    try{ sessionStorage.setItem('ds_customer_main_mode', mode); }catch(_){ }
    const targetTab = (mode === 'dogs') ? 'dogs' : ((mode === 'contract') ? 'contract' : 'documents');
    try{
      const __origShowPanelCustomer = showPanel;
      showPanel = function(id){
        const wanted = String(id || '');
        if(mode === 'stay' && wanted === 'editor') return __origShowPanelCustomer('editor');
        return __origShowPanelCustomer(targetTab);
      };
    }catch(_){ }
    try{
      const __origSelectTabCustomer = selectTab;
      selectTab = function(tabId){
        const wanted = String(tabId || '');
        if(mode === 'stay' && wanted === 'editor') return __origSelectTabCustomer('editor');
        return __origSelectTabCustomer((wanted === 'home') ? 'home' : targetTab);
      };
    }catch(_){ }
    try{
      if(!window.__dsCustomerDogsClickLock){
        window.__dsCustomerDogsClickLock = true;
        document.addEventListener('click', function(ev){
          const btn = ev.target && ev.target.closest ? ev.target.closest('.tab') : null;
          if(!btn) return;
          const t = String(btn.dataset.tab || '');
          if(t !== targetTab){ ev.preventDefault(); ev.stopPropagation(); try{ enforceCustomerMainCustomerModeUI(); }catch(_){ } }
        }, true);
      }
    }catch(_){ }
    try{
      if(window.__dsCustomerDogsModeTimer) clearInterval(window.__dsCustomerDogsModeTimer);
      window.__dsCustomerDogsModeTimer = setInterval(function(){ try{ if(isCustomerMainMode()) enforceCustomerMainCustomerModeUI(); }catch(_){ } }, 600);
    }catch(_){ }
    enforceCustomerMainCustomerModeUI();
    const ctx = getCustomerMainDogsContext();
    if(mode === 'dogs'){
      renderDogs();
      try{ dsRenderCustomerModeDebug(ctx); }catch(_){ }
      const ownPet = ctx.pets[0] || null;
      setTimeout(function(){
        try{
          if(ownPet){
            openCpEditor('edit', ownPet.id || ownPet.petId || ownPet.dogId || '');
          }else{
            openCpEditor('new');
            const use = document.getElementById('useExistingCustomer');
            const sel = document.getElementById('customerSelect');
            const useExisting = !!(ctx.customer && !ctx.isShadowCustomer && ctx.customerId);
            if(use) use.checked = useExisting;
            try{ refreshCustomerSelect(); }catch(_){ }
            if(useExisting && sel){
              sel.value = String(ctx.customerId || '');
              try{ setCustomerFieldsDisabled(true); }catch(_){ }
              try{ fillCustomerFieldsOnly(ctx.customerId); }catch(_){ }
            }else{
              try{ setCustomerFieldsDisabled(false); }catch(_){ }
              try{ fillCpCustomerFieldsFromObject(ctx.customer || {}); }catch(_){ }
            }
          }
        }catch(e){ console.error('customer main dogs open failed', e); }
      }, 80);
      cpSetStatus('Kundenmodus: Kunde/Hund');
    } else if(mode === 'contract'){
      try{ if(typeof selectTab === 'function') selectTab('contract'); }catch(_){ }
      setTimeout(prepareCustomerContractMode, 80);
      cpSetStatus('Kundenmodus: Betreuungsvertrag');
    } else if(mode === 'stay'){
      try{ if(typeof selectTab === 'function') selectTab('documents'); }catch(_){ }
      setTimeout(prepareCustomerStayMode, 100);
      cpSetStatus('Kundenmodus: Neuer Aufenthalt');
    }
  }catch(e){ console.error('initCustomerMainMode failed', e); }
}
async function initCustomerPortal(){
  // Kunden sollen NICHT in die interne App – bei Direktaufruf app.html ins Kundenportal umleiten
  try{
    const p = (location && location.pathname) ? location.pathname.toLowerCase() : '';
    const qs = new URLSearchParams((location && location.search) ? location.search : '');
    const allowMainCustomerMode = ['dogs','contract','stay'].includes(String(qs.get('customer_mode')||''));
    if((p.endsWith('/app.html') || p.endsWith('app.html')) && !allowMainCustomerMode){
      location.replace('customer.html');
      return;
    }
  }catch(_){}

  hideStaffUIForCustomer();
  updateSyncUI();
  try{ await loadTemplates(); }catch(_){ }
  // Logout Button
  const btn = document.getElementById('btnCustomerLogout');
  if(btn) btn.onclick = async ()=>{ try{ await CLOUD.auth.signOut(); }catch(_){ } };
  // Live-Listener: offene Aufgaben für diesen Kunden
  const uid = CLOUD.user?.uid;
  const email = String(CLOUD.user?.email || '').trim().toLowerCase();
  if(!uid && !email) return;
  const listEl = document.getElementById('customerTaskList');
  const subtitle = document.getElementById('customerPortalSubtitle');
  const editor = document.getElementById('customerTaskEditor');
  if(editor) editor.style.display = 'none';
  function getLocalCustomerTasks(){return [];}
  // Back
  const btnBack = document.getElementById('btnCustomerTaskBack');
  if(btnBack) btnBack.onclick = ()=>{
    const listCard = document.getElementById('customerTaskListCard');
    if(editor) editor.style.display = 'none';
    if(listEl) listEl.style.display = '';
    if(listCard) listCard.style.display = 'block';
    try{ listCard?.scrollIntoView({behavior:'smooth', block:'start'}); }catch(_){ }
  };
  const tasksCol = cloudTasksCol();
  const proposalsCol = cloudProposalsCol();
  const unsubs = [];
  const taskBuckets = new Map();
  const proposalBuckets = new Map();
  const flattenBuckets=(buckets)=>{
    const merged=new Map();
    buckets.forEach(map=>map.forEach((value,key)=>merged.set(key,value)));
    return Array.from(merged.values());
  };
  const publish = ()=>{
    const merged = new Map();
    flattenBuckets(taskBuckets).forEach(t=> merged.set(String(t.id||t.taskId||Math.random()), t));
    getLocalCustomerTasks().forEach(t=>{
      const key = String(t.id || t.taskId || Math.random());
      if(!merged.has(key)) merged.set(key, t);
    });
    const allTasks = Array.from(merged.values()).sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
    const tasks=allTasks.filter(t=>String(t.status||'open').toLowerCase()==='open');
    window.__dsCustomerTasks=allTasks;
    window.__dsCustomerProposals=flattenBuckets(proposalBuckets).sort((a,b)=>Number(b.submittedAt||b.updatedAt||0)-Number(a.submittedAt||a.updatedAt||0));
    try{ window.dispatchEvent(new CustomEvent('ds-customer-data-ready')); }catch(_){ }
    renderCustomerTaskList(tasks);
    if(subtitle){
      subtitle.textContent = tasks.length ? 'Doggy Style Hundepension hat Aufgaben für dich.' : 'Aktuell liegen keine Aufgaben für dich vor.';
    }
  };
  const attach=(collection,field,value,key,buckets,label)=>{
    if(!collection || !value) return;
    const bucket=new Map(); buckets.set(key,bucket);
    unsubs.push(collection.where(field,'==',value).onSnapshot((snap)=>{
      bucket.clear();
      snap.forEach(doc=>bucket.set(doc.id,{id:doc.id,...doc.data()}));
      publish();
    },err=>{
      console.error(label+' listener',err); publish();
      if(subtitle && !getLocalCustomerTasks().length) subtitle.textContent='Fehler beim Laden der Kundendaten.';
    }));
  };
  if(uid){ attach(tasksCol,'customerUid',uid,'task-uid',taskBuckets,'customer tasks'); attach(proposalsCol,'customerUid',uid,'proposal-uid',proposalBuckets,'customer proposals'); }
  // Customer queries use the authenticated UID exclusively.
  if(!uid && !email) publish();
  window.__dsCustomerPortalUnsubscribe=()=>{ unsubs.splice(0).forEach(fn=>{try{fn();}catch(_){}}); };
  function renderCustomerTaskList(tasks){
    if(!listEl) return;
    window.__dsCustomerTasks = Array.isArray(tasks) ? tasks.slice() : [];
    listEl.innerHTML = '';
    if(!tasks.length){
      listEl.innerHTML = `<div class="muted">— keine Aufgaben —</div>`;
      return;
    }
    tasks.forEach((t, idx)=>{
      const taskId = String(t.id || t.taskId || idx);
      const row = document.createElement('div');
      row.className = 'list-item';
      row.dataset.taskId = taskId;
      row.style.cursor = 'pointer';
      const when = t.createdAt ? fmtDT(t.createdAt) : '';
      row.innerHTML = `<div><strong>${escapeHtml(t.title||'Aufgabe')}</strong><small>${escapeHtml(t.templateId||'')}${when?(' · '+when):''}</small></div>`;
      const actions = document.createElement('div');
      actions.className = 'actions';
      const btnOpen = document.createElement('button');
      btnOpen.type = 'button';
      btnOpen.className = 'smallbtn';
      btnOpen.textContent = 'Öffnen';
      btnOpen.dataset.taskId = taskId;
      btnOpen.onclick = (ev)=>{ ev.preventDefault(); ev.stopPropagation(); if(window.__dsOpenCustomerTaskById) window.__dsOpenCustomerTaskById(taskId); else openCustomerTask(t); };
      row.onclick = ()=>{ if(window.__dsOpenCustomerTaskById) window.__dsOpenCustomerTaskById(taskId); else openCustomerTask(t); };
      actions.appendChild(btnOpen);
      row.appendChild(actions);
      listEl.appendChild(row);
    });
  }
  let _draftTimer = null;
  async function openCustomerTask(task){
    if(!task || !task.templateId) return;
    const t = getTemplate(task.templateId);
    if(!t){ alert('Vorlage nicht gefunden.'); return; }
    const isCustomerPortal = !!document.getElementById('customerPortal');
    const listCard = document.getElementById('customerTaskListCard');
    if(listEl) listEl.style.display = 'none';
    if(listCard) listCard.style.display = 'none';
    if(editor) { editor.style.display = 'block'; editor.hidden = false; }
    try{ editor?.scrollIntoView({behavior:'smooth', block:'start'}); }catch(_){ }

    const titleEl = document.getElementById('editorTitle') || document.getElementById('customerTaskTitle');
    const metaEl = document.getElementById('editorMeta') || document.getElementById('customerTaskMeta');
    const hint = document.getElementById('customerTaskSaveHint');
    const root = document.getElementById('formRoot') || document.getElementById('customerTaskFormRoot');
    const dsgvo = document.getElementById('dsGvoText');
    const backBtn = document.getElementById('btnCustomerTaskBack');
    const submitBtn = document.getElementById('btnCustomerTaskSubmit');
    const nameEl = document.getElementById('docName');
    const dogSel = document.getElementById('dogSelect');
    if(titleEl) titleEl.textContent = task.title || t.name || 'Aufgabe';
    if(metaEl) metaEl.textContent = `Formular: ${t.name||task.templateId}`;
    if(hint) hint.textContent = '';

    const mergedFields = Object.assign({}, (task.payloadSubmitted && task.payloadSubmitted.fields) || {}, (task.payloadDraft && task.payloadDraft.fields) || {});
    const mergedMeta = Object.assign({}, (task.payloadSubmitted && task.payloadSubmitted.meta) || {}, (task.payloadDraft && task.payloadDraft.meta) || {});
    currentDoc = {
      id: `customer_task_${String(task.id || task.taskId || Date.now())}`,
      sourceTaskId: String(task.id || task.taskId || ''),
      templateId: task.templateId,
      templateName: t.name || task.templateId,
      title: task.title || t.name || 'Aufgabe',
      dogId: task.dogId || '',
      customerId: task.customerId || '',
      fields: mergedFields,
      meta: mergedMeta,
      saved: false,
      signature: task.signature || null
    };
    if(nameEl) nameEl.value = currentDoc.title || '';
    if(dogSel){
      dogSel.innerHTML = currentDoc.dogId ? `<option value="${escapeHtml(currentDoc.dogId)}">${escapeHtml(currentDoc.dogId)}</option>` : '';
      dogSel.value = currentDoc.dogId || '';
      dogSel.style.display = 'none';
    }
    if(root) root.innerHTML = '';
    renderForm(currentDoc);
    if(dsgvo) dsgvo.textContent = (t.dsGvoNote || '');
    const versionBox = document.getElementById('versionBox');
    if(versionBox) versionBox.style.display = 'none';

    const saveDraftNow = async ()=>{
      try{
        const { fields, meta } = collectForm();
        currentDoc.fields = fields; currentDoc.meta = meta;
        const draftKey='ds_customer_task_drafts_v3:'+firebase.auth().currentUser.uid;
        const drafts=JSON.parse(localStorage.getItem(draftKey)||'{}')||{};
        drafts[String(task.id||task.taskId||currentDoc.id)]={fields,meta,updatedAt:Date.now()};
        localStorage.setItem(draftKey,JSON.stringify(drafts));
        if(hint) hint.textContent = `✅ Entwurf auf diesem Gerät gespeichert: ${fmtDT(Date.now())}`;
      }catch(e){
        console.error('draft save',e);
        if(hint) hint.textContent='❌ Entwurf konnte nicht gespeichert werden.';
      }
    };
    let _draftTimer = null;
    const scheduleDraftSave = ()=>{
      clearTimeout(_draftTimer);
      _draftTimer = setTimeout(()=>saveDraftNow(), 600);
      if(hint) hint.textContent = '… speichert …';
    };
    if(root){
      root.querySelectorAll('[data-key]').forEach(inp=>{
        inp.addEventListener('input', scheduleDraftSave, {passive:true});
        inp.addEventListener('change', scheduleDraftSave, {passive:true});
      });
    }
    if(backBtn) backBtn.onclick = ()=>{
      if(editor) editor.style.display = 'none';
      if(listEl) listEl.style.display = '';
      if(listCard) listCard.style.display = 'block';
    };
    if(submitBtn) submitBtn.onclick = async ()=>{
      if(!confirm('Formular absenden?')) return;
      try{
        const { fields, meta } = collectForm();
        currentDoc.fields=fields; currentDoc.meta=meta;
        const errs=validate(currentDoc,t);
        if(errs.length){ alert('Bitte prüfen: '+errs.join(', ')); return; }
        const result=await dsSubmitCustomerPortalProposal({
          templateId:task.templateId,title:task.title||t.name||task.templateId,
          customerId:String(task.customerId||''),petId:String(task.petId||task.dogId||''),
          sourceTaskId:String(task.id||task.taskId||''),
          payloadSubmitted:{fields,meta}
        });
        if(result && result.ok){
          alert('✅ Danke! Formular wurde übermittelt.');
          if(editor) editor.style.display='none'; if(listEl) listEl.style.display=''; if(listCard) listCard.style.display='block';
        }else{
          alert('⚠️ Formular lokal vorgemerkt. Die Übertragung wird automatisch erneut versucht.');
        }
      }catch(e){ console.error('submit',e); alert('❌ Absenden fehlgeschlagen: '+(e.message||e)); }
    };
  }
  window.__dsOpenCustomerTask = openCustomerTask;
  window.__dsOpenCustomerTaskById = function(id){
    const tasks = Array.isArray(window.__dsCustomerTasks) ? window.__dsCustomerTasks : [];
    const found = tasks.find(x => String((x && (x.id || x.taskId)) || '') === String(id||''));
    if(found) return openCustomerTask(found);
    console.warn('customer task not found', id, tasks.length);
    return null;
  };
}


