function showPanel(id){
  document.querySelectorAll(".panel").forEach(p=>{
    p.classList.toggle("is-active", p.id === id);
  });
  // IMPORTANT: Each panel must trigger its renderer when activated.
  // Otherwise, after Reload/Login the panel can remain empty because its DOM
  // was never hydrated from state/cloud.
  if(id === "home"){
    renderDashboard();
    renderRecent();
  }
  if(id === "dogs"){
    try{ renderDogs(); }catch(_){ }
  }
  if(id === "invoices"){
    window.DSInvoiceWorkspace?.enter();
  } else {
    window.DSInvoiceWorkspace?.leave();
  }
  if(id === "contract"){
    renderContractPanel();
  }
  if(id === "workforms"){
    renderWorkformsPanel();
  }
  if(id === "hygiene"){
    renderHygienePanel();
  }
  if(id === "medication"){
    try{ renderMedicationPanel(); }catch(_){ }
  }
  if(id === "analytics"){
    renderAnalyticsPanel();
    window.DSSettingsWorkspace?.prepareExportMonth();
  }
  if(id === "statistics"){
    try{ renderStatisticsPanel(); }catch(_){ }
  }
  if(id === "calendar"){
    window.DSCalendarEvents?.show({
      selectedDate: calendarFormDate,
      showDay: selectCalendarDay,
      refresh: refreshCalendar
    });
    refreshCalendar();
  } else {
    window.DSCalendarEvents?.leave();
  }
  if(id === "settings"){
    window.DSPortalActions?.renderBankSettings();
    try{
      initProfiSettingsBindings();
      renderStaffSettings();
      renderPolicySettings();
      renderSettingsLegal();
      window.DSSettingsWorkspace?.enter();
    }catch(_){ }
  }

  if(id === "compliance"){
    try{ bindComplianceActions(); renderCompliancePanel(); }catch(_){ }
  }
  if(id === "chat"){
    try{ dsSetChatExplicitOpen('staff', true); }catch(_){ }
    try{ renderAdminChatPanel(); }catch(_){ }
  }
  if(id === "inbox"){
    try{ dsResetInboxDetailView(); }catch(_){ }
  }
}
