function completeHygieneLog(id){
  ensureStateShape();
  const log = (state.hygiene.logs||[]).find(x=>x.id===id);
  if(!log) return;
  // Staff aus Auswahl/Freitext übernehmen (wenn vorhanden)
  const preset = (document.getElementById('hygStaffPreset')?.value || '').trim();
  const free = (document.getElementById('hygStaffFree')?.value || '').trim();
  const staffName = (free || preset || '').trim();
  if(!staffName && !(log.staff?.free || log.staff?.preset)){
    const entered = prompt('Wer hat es durchgeführt? (Name)', '');
    if(entered === null) return;
    log.staff = { preset: null, free: (entered||'').trim() || null };
  } else if(staffName){
    log.staff = { preset: preset || null, free: free || null };
  }
  log.status = 'erledigt';
  log.updatedAt = new Date().toISOString();
  saveState();
  renderHygienePanel();
  renderHygieneDashboard();
}
function editHygieneLog(id){
  const log = (state.hygiene.logs||[]).find(x=>x.id===id);
  if(!log) return;
  const newNote = prompt('Notiz bearbeiten (leer lassen, um zu löschen):', log.note || '');
  if(newNote === null) return;
  log.note = (newNote || '').trim() || null;
  log.updatedAt = new Date().toISOString();
  saveState();
  renderHygienePanel();
  renderHygieneDashboard();
}
function markWeeklyTaskDone(taskId){
  const t = (state.hygiene.weeklyTasks||[]).find(x=>x.id===taskId);
  if(!t) return;
  const now = new Date();
  t.lastDone = now.toISOString();
  // create auto log entry (wer hat es gemacht? -> Auswahl + Freitext)
  const preset = (document.getElementById('hygStaffPreset')?.value || 'Raphael').trim();
  const free = (document.getElementById('hygStaffFree')?.value || '').trim();
  const staff = { preset: preset || null, free: free || null };
  state.hygiene.logs.unshift({
    id: uid(),
    date: todayISO(),
    area: "Außenbereich",
    action: "Grundreinigung",
    status: "erledigt",
    reason: null,
    staff,
    note: `Wochenaufgabe: ${t.title}`,
    createdAt: now.toISOString(),
    updatedAt: null,
    _deleted: false
  });
  saveState();
  renderHygienePanel();
  renderHygieneDashboard();
}
function markMonthlyTaskDone(taskId, outcome){
  const t = (state.hygiene.monthlyTasks||[]).find(x=>x.id===taskId);
  if(!t) return;
  const now = new Date();
  // Outcome only relevant for pest monitoring
  if(t.mode === "pest"){
    // default outcome if not given: "no"
    const oc = outcome || "no";
    t.lastOutcome = oc;
    t.lastOutcomeAt = now.toISOString();
  }
  t.lastDone = now.toISOString();
  const preset = (document.getElementById('hygStaffPreset')?.value || 'Raphael').trim();
  const free = (document.getElementById('hygStaffFree')?.value || '').trim();
  const staff = { preset: preset || null, free: free || null };
  // Create auto log entry
  let note = `Monatsaufgabe: ${t.title}`;
  let status = "erledigt";
  let area = (t.area || "Innenräume");
  let action = "Monatsaufgabe";
  if(t.mode === "pest"){
    if(t.lastOutcome === "no"){
      note = `Schädlingsmonitoring: Kein Befall festgestellt. (${t.title})`;
    } else if(t.lastOutcome === "inf"){
      // NEW (Betriebs-Check PRO): structured documentation (behördentauglich)
      const pestType = (prompt('Befall – Art (z.B. Nager/Insekten/Ameisen/Fliegen/Sonstiges):', '') || '').trim();
      if(!pestType){ alert('Befall: Bitte Art angeben.'); return; }
      const pestLoc = (prompt('Befall – Ort (z.B. Futterlager/Außenbereich/Tierbereich/Gebäude):', '') || '').trim();
      if(!pestLoc){ alert('Befall: Bitte Ort angeben.'); return; }
      const pestAction = (prompt('Sofortmaßnahme (z.B. Reinigung/Köder ersetzt/Bereich gesperrt/Schädlingsbekämpfer informiert):', '') || '').trim();
      if(!pestAction){ alert('Befall: Bitte Sofortmaßnahme angeben.'); return; }
      const followUp = (prompt('Nachkontrolle Datum (YYYY-MM-DD):', todayISO()) || '').trim();
      if(!/^\d{4}-\d{2}-\d{2}$/.test(followUp)) { alert('Befall: Bitte gültiges Datum YYYY-MM-DD eingeben.'); return; }
      // store details on the task for later display / audit
      t.lastPestDetails = { type: pestType, location: pestLoc, action: pestAction, followUpDate: followUp, notedAt: now.toISOString() };
      note = `Schädlingsmonitoring: Befall festgestellt. Art: ${pestType} · Ort: ${pestLoc} · Maßnahme: ${pestAction} · Nachkontrolle: ${followUp}`;

      // Additionally create a follow-up action entry: Schädlingsbekämpfer anfordern
      try{
        state.hygiene.logs.unshift({
          id: uid(),
          date: todayISO(),
          area: area,
          action: "Schädlingsbekämpfer anfordern",
          status: "fällig",
          reason: null,
          staff,
          note: "Auslöser: Schädlingsmonitoring → Befall festgestellt.",
          createdAt: now.toISOString(),
          updatedAt: null,
          _deleted: false
        });
      }catch(_){ }
    }
  }
  state.hygiene.logs.unshift({
    id: uid(),
    date: todayISO(),
    area: area,
    action: action,
    status: status,
    reason: null,
    staff,
    note: note,
    createdAt: now.toISOString(),
    updatedAt: null,
    _deleted: false
  });
  saveState();
  renderHygienePanel();
  renderHygieneDashboard();
}
