let cpVaccinationPassDataUrl = "";
let cpProfilePhotoDataUrl = "";

async function cpWaitForFirebaseUser(timeoutMs){
  const timeout = Number(timeoutMs||8000);
  const started = Date.now();
  async function ensureInit(){
    try{
      if(!(window.firebase && firebase.auth && firebase.storage)){
        if(typeof cloudInit==='function') await cloudInit();
      } else if(!(window.CLOUD && CLOUD.auth)){
        if(typeof cloudInit==='function') await cloudInit();
      }
    }catch(_){ }
  }
  await ensureInit();
  try{
    if(window.firebase && firebase.auth){
      let u = (window.CLOUD && CLOUD.auth && CLOUD.auth.currentUser) || firebase.auth().currentUser || (window.CLOUD && CLOUD.user) || null;
      if(u) return u;
      u = await new Promise((resolve)=>{
        let done = false;
        const finish = (val)=>{ if(done) return; done=true; try{ unsub && unsub(); }catch(_){ } resolve(val||null); };
        const remaining = Math.max(250, timeout - (Date.now()-started));
        const timer = setTimeout(()=>finish((window.CLOUD && CLOUD.auth && CLOUD.auth.currentUser) || (window.firebase&&firebase.auth?firebase.auth().currentUser:null) || (window.CLOUD && CLOUD.user) || null), remaining);
        let unsub = null;
        try{
          const auth = (window.CLOUD && CLOUD.auth) || firebase.auth();
          if(auth && auth.onAuthStateChanged){
            unsub = auth.onAuthStateChanged((user)=>{ clearTimeout(timer); finish(user || (window.CLOUD && CLOUD.user) || null); });
          } else {
            clearTimeout(timer); finish((window.CLOUD && CLOUD.user) || null);
          }
        }catch(_){ clearTimeout(timer); finish((window.CLOUD && CLOUD.user) || null); }
      });
      return u || null;
    }
  }catch(_){ }
  return (window.CLOUD && (CLOUD.user || (CLOUD.auth && CLOUD.auth.currentUser))) || null;
}

async function cpUploadPetPhotoToStorage(file,kind){
    if(!file)return '';const user=await cpWaitForFirebaseUser(8000);if(!user)throw new Error('Bitte anmelden.');
    if(!['profile','vaccpass'].includes(kind))throw new Error('Unbekannte Fotoart.');
    const ctx=DSWorkflow.context(),petId=String(cpEdit?.petId||''),mode=String(cpEdit?.mode||'');
    if(CLOUD.role==='customer' && (!ctx.verified || (petId && !ctx.pets.some(p=>p.id===petId))))throw new Error('Fremder Hund oder fehlende Zuordnung.');
    const prepared=await DSWorkflow.preparePetPhoto(file),sameEditor=()=>firebase.auth().currentUser?.uid===user.uid&&String(cpEdit?.petId||'')===petId&&String(cpEdit?.mode||'')===mode;
    if(!sameEditor())throw new Error('Konto oder geöffneter Hund wurde gewechselt.');
    if(!petId){const result=await DSWorkflow.prepareNewPetPhoto(prepared);if(!sameEditor())throw new Error('Konto oder geöffneter Hund wurde gewechselt.');return result;}
    const orgId=window.firebaseOrgId,path='orgs/'+orgId+'/pets/'+petId+'/'+kind+'_'+crypto.randomUUID()+'.'+({ 'image/jpeg':'jpg','image/png':'png' }[prepared.type]);
    cpSetStatus('Foto wird hochgeladen …');
    await firebase.storage().ref().child(path).put(prepared,{contentType:prepared.type,customMetadata:{orgId,petId,uploadedBy:user.uid,kind}});
    if(!sameEditor())throw new Error('Konto oder geöffneter Hund wurde gewechselt.');
    DSWorkflow.retainUploadedPhoto(path,prepared,user.uid);
    cpSetStatus('Foto hochgeladen. Änderung bitte zur Prüfung einreichen.');return 'ds-storage:'+path;
  }
let cpEditorSnapshot = "";
let cpDirty = false;
function cpSetStatus(msg, isError){
  const hint = document.getElementById("cpHint");
  if(!hint) return;
  hint.textContent = msg || "";
  hint.style.color = isError ? "#b42318" : "";
}
function cpCaptureSnapshot(){
  try{
    const box = document.getElementById("cpEditor");
    if(!box) return "";
    const data = {};
    box.querySelectorAll("input, textarea, select").forEach((el)=>{
      const id = el.id || el.name;
      if(!id) return;
      if(id === "btnCpSave" || id === "btnCpCancel" || id === "btnCpAddAnotherDog") return;
      if(el.type === "file") return;
      data[id] = (el.type === "checkbox") ? !!el.checked : (el.value ?? "");
    });
    data.__vaccinationPassPhoto = cpVaccinationPassDataUrl || "";
    data.__profilePhoto = cpProfilePhotoDataUrl || "";
    return JSON.stringify(data);
  }catch(_){ return ""; }
}
function cpUpdateDirty(){
  cpDirty = (cpCaptureSnapshot() !== cpEditorSnapshot);
  if(!cpDirty){
    const hint = document.getElementById("cpHint");
    if(hint && hint.textContent === "Ungespeicherte Änderungen.") cpSetStatus("");
  }
}
function cpArmDirtyTracking(){
  const box = document.getElementById("cpEditor");
  if(!box || box.dataset.dirtyBound === "1") return;
  const mark = ()=>{ cpUpdateDirty(); if(cpDirty) cpSetStatus("Ungespeicherte Änderungen."); };
  box.addEventListener("input", mark, true);
  box.addEventListener("change", mark, true);
  box.dataset.dirtyBound = "1";
}
