function openCpEditor(mode, petId, ownerId){
  ensureStateShape();
  ensureContractDefaults();
  cpEdit.mode = mode || "new";
  cpEdit.petId = petId || "";
  const box = document.getElementById("cpEditor");
  cpEdit.ownerId = ownerId || "";
  if(box){box.dataset.mode=mode||"new";box.style.display="block";}
  try{ cpWirePetPhotoInputs(); }catch(_){ }
  const title = document.getElementById("cpEditorTitle");
  if(title) title.textContent = (mode==="edit") ? "Kunde & Hund bearbeiten" : "Kunde & Hund anlegen";
  refreshCustomerSelect();
  clearCpEditor();
  // Toggle handler
  const use = document.getElementById("useExistingCustomer");
  if(use){
    use.onchange = ()=>{
      const useExisting = use.checked;
      setCustomerFieldsDisabled(useExisting);
    };
  }
  if(mode==="edit" && petId){
    const pet = getPet(petId);
    if(pet){
      // Bei Edit: bestehenden Kunden nutzen + auswählen
      const useExisting = document.getElementById("useExistingCustomer");
      if(useExisting) useExisting.checked = true;
      refreshCustomerSelect();
      const sel = document.getElementById("customerSelect");
      if(sel) sel.value = pet.customerId || "";
      setCustomerFieldsDisabled(false); // beim Edit darfst du den Kunden auch korrigieren
      fillCpEditorForPet(pet);
    }
  } else if(ownerId && getCustomer(ownerId)){
    if(use) use.checked=true;
    document.getElementById("customerSelect").value=ownerId;
    fillCustomerFieldsOnly(ownerId);
    setCustomerFieldsDisabled(mode!=="owner");
    if(title) title.textContent=mode==="owner"?"Halter bearbeiten":"Hund für "+getCustomer(ownerId).name+" anlegen";
  } else {
    // New: wenn Kunden vorhanden, Auswahl anbieten, aber standardmäßig aus
    setCustomerFieldsDisabled(false);
  }
  // Dauermedikation (Plan) inline im Hund-Editor
  try{ cpMedEnsureInlineUI(); }catch(_){ }
  try{ cpMedRenderInlineList(); }catch(_){ }
  try{ ensureAddAnotherDogButton(); }catch(_){ }
  try{ updateAddAnotherDogButtonVisibility(); }catch(_){ }
  try{ cpArmDirtyTracking(); }catch(_){ }
  cpEditorSnapshot = cpCaptureSnapshot();
  cpDirty = false;
  cpWirePetPhotoInputs();
  cpSetStatus("");
  const __reviewOpening = !!((typeof window !== 'undefined' && window.__dsProposalReviewOpening) || (__dsProposalReview && __dsProposalReview.active));
  if(box && !__reviewOpening) box.scrollIntoView({behavior:"smooth", block:"start"});
}
// === 2A.x Erweiterung: "Weiteren Hund" für bestehenden Kunden ===
function getCurrentCpCustomerId(){
  try{
    if(cpEdit && cpEdit.mode==="edit" && cpEdit.petId){
      const rawPid = String(cpEdit.petId || '').trim();
      let p = null;
      try{ p = getPet(rawPid); }catch(_){ p = null; }
      try{ if(!p && typeof getPetByDogId === 'function') p = getPetByDogId(rawPid) || null; }catch(_){ }
      try{
        if(!p){
          const pets = asArray(state && (((state.pets||[]).length ? state.pets : state.dogs) || []));
          const pid = norm(rawPid);
          p = pets.find(function(x){
            return norm((x && (x.id || x.petId || x.dogId || x.legacyDogId || '')) || '') === pid;
          }) || null;
        }
      }catch(_){ }
      if(p && (p.customerId || p.ownerId)) return String(p.customerId || p.ownerId || '');
      try{
        if(rawPid && typeof getCustomerByDogId === 'function'){
          const c = getCustomerByDogId(rawPid);
          if(c && (c.id || c.customerId)) return String(c.id || c.customerId || '');
        }
      }catch(_){ }
    }
    const use = document.getElementById("useExistingCustomer");
    const sel = document.getElementById("customerSelect");
    if(use && use.checked && sel && sel.value) return sel.value;
    if(sel && sel.value) return sel.value;
  }catch(_){ }
  return "";
}

