function dsCountVisibleDogsUiMarkers(){
  try{
    let seenMax = 0, seenRex = 0, seenEdit = 0;
    const roots = dsCollectInspectableRoots();
    roots.forEach(function(root){
      try{
        const txt = lower((root && root.body ? root.body.innerText : root && root.innerText) || '');
        if(/max mustermann/.test(txt)) seenMax += 1;
        if(/\brex\b/.test(txt)) seenRex += 1;
      }catch(_){ }
      try{
        const btns = root && root.querySelectorAll ? Array.from(root.querySelectorAll('button, .smallbtn, [data-e="1"], [data-pet-edit-id]')) : [];
        btns.forEach(function(btn){
          try{ if(/bearbeiten/i.test(String(btn.textContent || btn.value || ''))) seenEdit += 1; }catch(_){ }
        });
      }catch(_){ }
    });
    return { seenMax: seenMax||0, seenRex: seenRex||0, seenEdit: seenEdit||0 };
  }catch(_){ return { seenMax:0, seenRex:0, seenEdit:0 }; }
}

function dsWaitForDogsUiReady(row, token, timeoutMs, onReady, onTimeout){
  timeoutMs = Number(timeoutMs || 0) || 4500;
  try{ if(row && typeof row === 'object'){ row.__openDiagObserverHit = '0'; row.__openDiagSeenMax='0'; row.__openDiagSeenRex='0'; row.__openDiagSeenEdit='0'; row.__openDiagAfterRender='0'; row.__openDiagEditVisible='0'; row.__openDiagPickedVisible='0'; row.__openDiagPickedBy='--'; row.__openDiagPickedRect='--'; row.__openDiagClicked='0'; } }catch(_){ }
  let done = false;
  let obs = null;
  const started = Date.now();
  const finish = function(ok, reason){
    try{ if(done) return; }catch(_){ }
    done = true;
    try{ if(obs) obs.disconnect(); }catch(_){ }
    const counts = dsCountVisibleDogsUiMarkers();
    try{ if(row && typeof row === 'object'){ row.__openDiagSeenMax=String(counts.seenMax||0); row.__openDiagSeenRex=String(counts.seenRex||0); row.__openDiagSeenEdit=String(counts.seenEdit||0); row.__openDiagAfterRender = ok ? '1':'0'; } }catch(_){ }
    try{ if(ok){ onReady && onReady(reason || 'ready', counts); } else { onTimeout && onTimeout(reason || 'timeout', counts); } }catch(_){ }
  };
  const check = function(stage){
    try{ if(window.__dsProposalUiOpenToken !== token) return finish(false, 'token'); }catch(_){ }
    let counts = { seenMax:0, seenRex:0, seenEdit:0 };
    try{ counts = dsCountVisibleDogsUiMarkers(); }catch(_){ }
    try{ if(row && typeof row === 'object'){ row.__openDiagSeenMax=String(counts.seenMax||0); row.__openDiagSeenRex=String(counts.seenRex||0); row.__openDiagSeenEdit=String(counts.seenEdit||0); } }catch(_){ }
    let hit = false;
    try{
      const dogList = document.getElementById('dogList');
      const listItems = dogList && dogList.querySelectorAll ? dogList.querySelectorAll('.item').length : 0;
      hit = !!(listItems || counts.seenMax || counts.seenRex || counts.seenEdit);
      if(hit && row && typeof row === 'object') row.__openDiagObserverHit = stage === 'observer' ? '1' : row.__openDiagObserverHit || '0';
    }catch(_){ }
    if(hit) return finish(true, stage || 'check');
    if((Date.now() - started) >= timeoutMs) return finish(false, 'timeout');
    try{ requestAnimationFrame(function(){ check('raf'); }); }catch(_){ setTimeout(function(){ check('timer'); }, 120); }
  };
  try{
    obs = new MutationObserver(function(){
      try{ if(row && typeof row === 'object') row.__openDiagObserverHit = '1'; }catch(_){ }
      check('observer');
    });
    obs.observe(document.documentElement || document.body || document, { childList:true, subtree:true, attributes:false, characterData:false });
  }catch(_){ }
  setTimeout(function(){ check('start'); }, 80);
}

function dsCollectInspectableRoots(){
  try{
    const roots = [];
    const seen = new Set();
    const walk = function(root){
      try{
        if(!root || seen.has(root)) return;
        seen.add(root);
        roots.push(root);
        const nodes = root.querySelectorAll ? Array.from(root.querySelectorAll('*')) : [];
        nodes.forEach(function(el){ try{ if(el && el.shadowRoot) walk(el.shadowRoot); }catch(_){ } });
      }catch(_){ }
    };
    walk(document);
    return roots;
  }catch(_){ return [document]; }
}

function dsScanDogsDom(){
  try{
    const roots = dsCollectInspectableRoots();
    const seenItems = new Set();
    const seenRows = new Set();
    const seenBtns = new Set();
    const items = [];
    const petRows = [];
    const buttons = [];
    let rexCount = 0;
    let customerCount = 0;
    roots.forEach(function(root){
      try{
        const localItems = root.querySelectorAll ? Array.from(root.querySelectorAll('#dogList .item, section.panel#dogs .item, .panel#dogs .item, #dogs .item')) : [];
        localItems.forEach(function(el){ if(el && !seenItems.has(el)){ seenItems.add(el); items.push(el); } });
      }catch(_){ }
      try{
        const localRows = root.querySelectorAll ? Array.from(root.querySelectorAll('[data-role="pet-row"]')) : [];
        localRows.forEach(function(el){ if(el && !seenRows.has(el)){ seenRows.add(el); petRows.push(el); } });
      }catch(_){ }
      try{
        const localBtns = root.querySelectorAll ? Array.from(root.querySelectorAll('button, .smallbtn, [data-e="1"], [data-pet-edit-id]')) : [];
        localBtns.forEach(function(el){
          try{
            if(!el || seenBtns.has(el)) return;
            const txt = norm((el.textContent || el.value || '') || '');
            if(!/bearbeiten/i.test(txt)) return;
            seenBtns.add(el);
            buttons.push(el);
          }catch(_){ }
        });
      }catch(_){ }
    });
    try{
      const rexSeen = new Set();
      items.forEach(function(el){
        try{
          if(!el || rexSeen.has(el)) return;
          rexSeen.add(el);
          const txt = lower((el.textContent || '') || '');
          if(/\brex\b/.test(txt)) rexCount += 1;
          if(/max mustermann/.test(txt)) customerCount += 1;
        }catch(_){ }
      });
    }catch(_){ }
    return { roots: roots.length || 0, items: items, petRows: petRows, buttons: buttons, rexCount: rexCount, customerCount: customerCount };
  }catch(_){ return { roots: 0, items: [], petRows: [], buttons: [], rexCount: 0, customerCount: 0 }; }
}

function dsCollectVisiblePetRowCandidates(){
  try{
    const scan = dsScanDogsDom();
    const items = (scan && Array.isArray(scan.items) && scan.items.length)
      ? scan.items
      : Array.from(document.querySelectorAll('#dogList .item, [data-tab-panel="dogs"] .item, #tab-dogs .item, section.panel#dogs .item, #dogs .item'));
    const seen = new Set();
    const out = [];
    const addItem = function(item, forcedBtn){
      try{
        if(!item || seen.has(item)) return;
        seen.add(item);
        const strong = item.querySelector ? item.querySelector('strong') : null;
        const strongTxt = norm((strong && strong.textContent) || '');
        const allBtns = item.querySelectorAll ? Array.from(item.querySelectorAll('button, .smallbtn, [data-e="1"], [data-pet-edit-id]')) : [];
        const btns = allBtns.filter(function(b){ return /bearbeiten/i.test(norm((b && b.textContent) || '')); });
        if(forcedBtn && !btns.includes(forcedBtn)) btns.unshift(forcedBtn);
        const itemTxt = norm((item.textContent || '') || '');
        const isPetLike = /^🐶/.test(strongTxt) || /bearbeiten/i.test(itemTxt) || /\brex\b/i.test(itemTxt);
        if(!isPetLike && !btns.length) return;
        let customerName = norm((item.dataset && item.dataset.customerName) || '');
        let customerId = norm((item.dataset && item.dataset.customerId) || (btns[0] && btns[0].dataset && btns[0].dataset.customerId) || '');
        if(!customerName || !customerId){
          let prev = item.previousElementSibling;
          while(prev){
            const ps = prev.querySelector ? prev.querySelector('strong') : null;
            const pst = norm((ps && ps.textContent) || '');
            if(pst && !/^🐶/.test(pst)){
              if(!customerName) customerName = pst.replace(/^[^\p{L}\p{N}]+/u,'').trim();
              if(!customerId) customerId = norm((prev.dataset && prev.dataset.customerId) || '');
              break;
            }
            prev = prev.previousElementSibling;
          }
        }
        const petName = (strongTxt || itemTxt).replace(/^🐶\s*/,'').trim();
        const btn = btns[0] || null;
        const petId = norm((item.dataset && item.dataset.petId) || (btn && btn.dataset && (btn.dataset.petEditId || btn.dataset.petId)) || '');
        out.push({ el:item, button:btn, petId:petId, customerId:customerId, customerName:customerName, petName:petName, hasDogIcon:/^🐶/.test(strongTxt) });
      }catch(_){ }
    };
    items.forEach(function(item){ addItem(item, null); });
    try{
      (scan.buttons || []).forEach(function(btn){
        try{
          const row = btn.closest ? (btn.closest('[data-role="pet-row"]') || btn.closest('.item')) : null;
          if(row) addItem(row, btn);
        }catch(_){ }
      });
    }catch(_){ }
    return out;
  }catch(_){ return []; }
}

function dsFindVisiblePetRowForProposal(row){
  try{
    ensureStateShape();
    try{ if(typeof renderDogs === 'function') renderDogs(); }catch(_){ }
    const payload = row && (row.payloadSubmitted || row.payloadDraft || row.payload || row.data || {}) || {};
    const customerPayload = (payload && payload.customer && typeof payload.customer === 'object') ? payload.customer : (row && row.customer && typeof row.customer === 'object' ? row.customer : {});
    const petPayload = (payload && payload.pet && typeof payload.pet === 'object') ? payload.pet : (row && row.pet && typeof row.pet === 'object' ? row.pet : {});
    const targetCid = norm((row && (row.__targetCustomerId || row.customerId)) || (customerPayload && (customerPayload.id || customerPayload.customerId)) || '');
    const targetPid = norm((row && (row.__targetPetId || row.petId)) || (petPayload && (petPayload.id || petPayload.petId)) || '');
    const targetCustomerName = lower((customerPayload && customerPayload.name) || (row && row.customerName) || '');
    const targetPetName = lower((petPayload && petPayload.name) || (row && row.petName) || '');
    const targetChip = norm((petPayload && petPayload.chipNumber) || (row && row.chipNumber) || '');
    const list = document.getElementById('dogList');
    const globalScan = dsScanDogsDom();
    let petRows = [];
    try{ if(list) petRows = Array.from(list.querySelectorAll('[data-role="pet-row"]')); }catch(_){ petRows = []; }
    try{ if(!petRows.length && globalScan && Array.isArray(globalScan.petRows) && globalScan.petRows.length) petRows = globalScan.petRows.slice(); }catch(_){ }
    let usedRaw = false;
    let candidates = [];
    if(petRows.length){
      candidates = petRows.map(function(el){
        const btn = el ? el.querySelector('[data-pet-edit-id],[data-e="1"],button,.smallbtn') : null;
        return {
          el: el,
          button: btn || null,
          petId: norm((el.dataset && el.dataset.petId) || (btn && btn.dataset && (btn.dataset.petEditId || btn.dataset.petId)) || ''),
          customerId: norm((el.dataset && el.dataset.customerId) || (btn && btn.dataset && btn.dataset.customerId) || ''),
          customerName: norm((el.dataset && el.dataset.customerName) || (btn && btn.dataset && btn.dataset.customerName) || ''),
          petName: norm((el.dataset && el.dataset.petName) || ''),
          petChip: norm((el.dataset && el.dataset.petChip) || ''),
        };
      });
    } else {
      usedRaw = true;
      candidates = dsCollectVisiblePetRowCandidates().map(function(x){
        return {
          el: x.el,
          button: x.button,
          petId: norm(x.petId || ''),
          customerId: norm(x.customerId || ''),
          customerName: norm(x.customerName || ''),
          petName: norm(x.petName || ''),
          petChip: '',
        };
      });
    }
    if(!candidates.length){
      try{ if(row && typeof row === 'object'){ row.__openDiagRowCount='0'; row.__openDiagRaw=usedRaw?'1':'0'; row.__openDiagBtnCount='0'; row.__openDiagRootCount=String((globalScan && globalScan.roots) || 0); row.__openDiagGlobalBtnCount=String((globalScan && globalScan.buttons && globalScan.buttons.length) || 0); row.__openDiagGlobalRexCount=String((globalScan && globalScan.rexCount) || 0); row.__openDiagGlobalCustomerCount=String((globalScan && globalScan.customerCount) || 0); } }catch(_){ }
      return null;
    }
    let hits = candidates.slice();
    if(targetPid){ const x = hits.filter(function(c){ return norm(c.petId||'') === targetPid; }); if(x.length) hits = x; }
    if(targetCid){
      const x = hits.filter(function(c){ return norm(c.customerId||'') === targetCid; });
      if(x.length) hits = x;
      else {
        const owned = candidates.filter(function(c){ return norm(c.customerId||'') === targetCid; });
        if(owned.length === 1) hits = owned;
      }
    }
    if(targetCustomerName){ const x = hits.filter(function(c){ return lower(c.customerName||'') === targetCustomerName; }); if(x.length) hits = x; }
    if(targetChip){ const x = hits.filter(function(c){ return norm(c.petChip||'') === targetChip; }); if(x.length) hits = x; }
    if(targetPetName){ const x = hits.filter(function(c){ return lower(c.petName||'') === targetPetName; }); if(x.length) hits = x; }
    if(!targetPid && !targetPetName && !targetChip && targetCid){
      const owned = candidates.filter(function(c){ return norm(c.customerId||'') === targetCid; });
      if(owned.length === 1) hits = owned;
    }
    let hit = null;
    if(hits.length === 1) hit = hits[0] || null;
    if(!hit && candidates.length === 1) hit = candidates[0] || null;
    const btnCount = candidates.filter(function(c){ return !!c.button; }).length;
    try{
      if(row && typeof row === 'object'){
        row.__openDiagRowCount = String(candidates.length || 0);
        row.__openDiagHitCount = String(hits.length || 0);
        row.__openDiagRowPetId = String((hit && hit.petId) || '--');
        row.__openDiagBtnPetId = String((hit && hit.button && hit.button.dataset && (hit.button.dataset.petEditId || hit.button.dataset.petId)) || '--');
        row.__openDiagRowCid = String((hit && hit.customerId) || '--');
        row.__openDiagBtnCount = String(btnCount || 0);
        row.__openDiagRaw = usedRaw ? '1':'0';
        row.__openDiagRootCount = String((globalScan && globalScan.roots) || 0);
        row.__openDiagGlobalBtnCount = String((globalScan && globalScan.buttons && globalScan.buttons.length) || 0);
        row.__openDiagGlobalRexCount = String((globalScan && globalScan.rexCount) || 0);
        row.__openDiagGlobalCustomerCount = String((globalScan && globalScan.customerCount) || 0);
      }
    }catch(_){ }
    if(!hit) return null;
    const petId = String((hit && hit.petId) || '').trim();
    return { row: hit.el || null, button: hit.button || null, petId: petId };
  }catch(_){ return null; }
}

