function dsGetNonCustomerCleanAppHref(){
  try{
    const url = new URL(String(location.href || ''), location.origin);
    const p = String((url.pathname || '')).toLowerCase();
    if(!(p.endsWith('/app.html') || p.endsWith('app.html'))) return '';
    const hadCustomerMode = url.searchParams.has('customer_mode');
    url.searchParams.delete('customer_mode');
    url.searchParams.delete('portal_start');
    const href = url.pathname + (url.searchParams.toString() ? ('?' + url.searchParams.toString()) : '') + (url.hash || '');
    return hadCustomerMode ? href : '';
  }catch(_){ return ''; }
}

function dsCustomerMainHasFreshLaunchMarker(){
  try{
    const qMode = String((new URLSearchParams(String((location && location.search) || '')).get('customer_mode') || '')).trim().toLowerCase();
    const ts = Number(sessionStorage.getItem('ds_customer_main_launch_ts') || 0) || 0;
    const handoff = (typeof dsGetCustomerMainHandoff === 'function') ? dsGetCustomerMainHandoff() : null;
    const handoffAuth = (handoff && handoff.auth && typeof handoff.auth === 'object') ? handoff.auth : {};
    const handoffCustomer = (handoff && handoff.customer && typeof handoff.customer === 'object') ? handoff.customer : {};
    const hasHandoff = !!(handoff || String(handoffAuth.uid || handoffAuth.email || handoffCustomer.customerId || handoffCustomer.id || handoffCustomer.email || '').trim());
    if(['dogs','contract','stay'].includes(qMode) && hasHandoff) return true;
    if(!ts || !hasHandoff) return false;
    return (Date.now() - ts) < (2 * 60 * 60 * 1000);
  }catch(_){ return false; }
}

function dsCustomerMainArtifactsMatchUser(){
  try{
    const role = String((window.CLOUD && CLOUD.role) || '').trim().toLowerCase();
    const rawUser = (window.CLOUD && (CLOUD.user || (CLOUD.auth && CLOUD.auth.currentUser)))
      || (window.firebase && firebase.auth ? firebase.auth().currentUser : null)
      || null;
    const rawProfile = (window.CLOUD && (CLOUD.userProfile || CLOUD.profile)) || {};
    const qMode = String((new URLSearchParams(String((location && location.search) || '')).get('customer_mode') || '')).trim().toLowerCase();
    const ssMode = String((sessionStorage.getItem('ds_customer_main_mode') || window.__dsCustomerMainModeActive || '')).trim().toLowerCase();
    const bodyMode = String((document && document.body && document.body.dataset && document.body.dataset.customerMode) || '').trim().toLowerCase();
    const hasMode = ['dogs','contract','stay'].includes(qMode) || ['dogs','contract','stay'].includes(ssMode) || ['dogs','contract','stay'].includes(bodyMode);
    if(!hasMode) return false;
    let handoff = null;
    try{ handoff = (typeof dsGetCustomerMainHandoff === 'function') ? dsGetCustomerMainHandoff() : null; }catch(_){ handoff = null; }
    const handoffAuth = (handoff && handoff.auth && typeof handoff.auth === 'object') ? handoff.auth : {};
    const handoffCustomer = (handoff && handoff.customer && typeof handoff.customer === 'object') ? handoff.customer : {};
    const handoffEmail = String(handoffAuth.email || handoffCustomer.email || sessionStorage.getItem('ds_customer_auth_handoff_email') || '').trim().toLowerCase();
    const handoffUid = String(handoffAuth.uid || handoffCustomer.portalUid || handoffCustomer.customerUid || handoffCustomer.uid || sessionStorage.getItem('ds_customer_auth_handoff_uid') || '').trim();
    const currentEmail = String((rawUser && rawUser.email) || rawProfile.email || '').trim().toLowerCase();
    const currentUid = String((rawUser && rawUser.uid) || rawProfile.uid || '').trim();
    if(role === 'customer'){
      if(handoffUid && currentUid) return handoffUid === currentUid;
      if(handoffEmail && currentEmail) return handoffEmail === currentEmail;
      return false;
    }
    if(handoffUid && currentUid && handoffUid === currentUid) return true;
    if(handoffEmail && currentEmail && handoffEmail === currentEmail) return true;
    return false;
  }catch(_){ return false; }
}

function saveState(){
  DSWorkflow.markWorkspaceEdit();
  try{ dsMarkStateOriginBeforeSave(); }catch(_){ }
  try{
    state._localUpdatedAt = Date.now();
    DSBrowserStore.cache(LS_KEY,JSON.stringify(state));
  }catch(e){
    console.error("Local save failed", e);
  }
  SYNC.localSavedAt = (state && state._localUpdatedAt) ? state._localUpdatedAt : Date.now();
  updateSyncUI();
  // Cloud Sync (Weg 2B): Änderungen nach außen spiegeln
  if(CLOUD.enabled && CLOUD.user && isStaff()) cloudSchedulePush();
  globalThis.DSAnalyticsView?.schedule();
}
function ensureDefaultDog(){
  if(!state.dogs || state.dogs.length===0){
    state.dogs=[{id:uid(),name:"— Bitte auswählen —",owner:"",phone:"",isPlaceholder:true}];
  }
}
function syncDogSelect(){
  const dogSel = $("#dogSelect");
  if(!dogSel) return;
  try{
    const scoped = (typeof dsGetScopedCustomerCollections === 'function') ? dsGetScopedCustomerCollections() : null;
    if(scoped){
      const customerName = String((scoped.customer && (scoped.customer.name || scoped.customer.displayName || scoped.customer.email)) || 'Kunde').trim();
      const pets = Array.isArray(scoped.pets) ? scoped.pets.slice() : [];
      if(!pets.length){
        dogSel.innerHTML = `<option value="">${escapeHtml('— noch kein Hund erfasst —')}</option>`;
        return;
      }
      dogSel.innerHTML = pets.map(p=>{
        const value = String(p.dogId || p.id || p.petId || '').trim();
        const name = String(p.name || p.petName || p.dogName || 'Hund').trim();
        const label = `${customerName ? customerName + ' – ' : ''}${name}`;
        return `<option value="${escapeHtml(value)}">${escapeHtml(label)}</option>`;
      }).join("");
      return;
    }
  }catch(_){ }
  ensureDefaultDog();
  dogSel.innerHTML=state.dogs.map(d=>{
    const label=d.isPlaceholder?d.name:`${d.owner?d.owner+" – ":""}${d.name}`;
    return `<option value="${d.id}">${escapeHtml(label)}</option>`;
  }).join("");
}
