function wireCoreUI(){
  try{
    if(window.__CORE_UI_WIRED__) return;
    window.__CORE_UI_WIRED__ = true;
    const btnLogin = document.getElementById("btnLogin");
    const btnRegister = document.getElementById("btnRegister");
    const btnLogout = document.getElementById("btnLogout");
    const btnLogoutApp = document.getElementById("btnLogoutApp");
    const btnLogoutBottom = document.getElementById("btnLogoutBottom");
    const btnNewStayTop = document.getElementById("btnNewStayTop");
    const btnNewStayOnPage = document.getElementById("btnNewStayOnPage");
    const btnQuickDogs = document.getElementById("btnQuickDogs");
    const btnQuickInvoices = document.getElementById("btnQuickInvoices");
    const loginEmail = document.getElementById("loginEmail");
    const loginPass = document.getElementById("loginPass");
    // Login/Register only if Cloud Auth is available
    if(btnLogin) btnLogin.onclick = async ()=>{
      setAuthMsg("");
      try{
        if(!CLOUD || !CLOUD.auth) throw new Error("Cloud/Auth nicht verfügbar");
        await CLOUD.auth.signInWithEmailAndPassword((loginEmail?.value||"").trim(), loginPass?.value||"");
      }catch(e){
        console.error(e);
        setAuthMsg(e.message||"Login fehlgeschlagen");
        try{ alert('Login fehlgeschlagen: '+(e.code||e.message||e)); }catch(_){ }
      }
    };
    if(btnRegister) btnRegister.onclick = async ()=>{
      setAuthMsg("");
      try{
        if(!CLOUD || !CLOUD.auth) throw new Error("Cloud/Auth nicht verfügbar");
        await CLOUD.auth.createUserWithEmailAndPassword((loginEmail?.value||"").trim(), loginPass?.value||"");
        setAuthMsg("Account erstellt. Bitte anmelden.");
      }catch(e){
        console.error(e);
        setAuthMsg(e.message||"Registrierung fehlgeschlagen");
        try{ alert('Registrierung fehlgeschlagen: '+(e.code||e.message||e)); }catch(_){ }
      }
    };
    if(btnLogout) btnLogout.onclick = async ()=>{ try{ await CLOUD?.auth?.signOut(); }catch(e){} };
    if(btnLogoutApp) btnLogoutApp.onclick = async ()=>{ try{ await CLOUD?.auth?.signOut(); }catch(e){} };
    if(btnLogoutBottom) btnLogoutBottom.onclick = ()=>performLogout();
    if(btnNewStayTop) btnNewStayTop.onclick = ()=>createStay();
    if(btnNewStayOnPage) btnNewStayOnPage.onclick = ()=>createStay();
    if(btnQuickDogs) btnQuickDogs.onclick = ()=>selectTab("dogs");
    if(btnQuickInvoices) btnQuickInvoices.onclick = ()=>selectTab("invoices");
    // Delegation: Buttons werden in einigen Render-Pfaden neu in den DOM geschrieben.
    // Daher zusätzlich Delegation (capture=true), damit der Klick immer greift (iOS/Safari inkl.).
    if(!window.__DELEGATED_CORE_UI__){
      window.__DELEGATED_CORE_UI__ = true;
      const handle = (ev)=>{
        const t = ev.target;
        const btn = t && t.closest ? t.closest('#btnNewStayTop, #btnNewStayOnPage, #btnQuickDogs, #btnQuickInvoices') : null;
        if(!btn) return;
        try{ ev.preventDefault(); }catch(_){ }
        try{ ev.stopPropagation(); }catch(_){ }
        const id = btn.id;
        if(id === "btnNewStayTop" || id === "btnNewStayOnPage") return createStay();
        if(id === "btnQuickDogs") return selectTab("dogs");
        if(id === "btnQuickInvoices") return selectTab("invoices");
      };
      document.addEventListener("click", handle, true);
      document.addEventListener("pointerup", handle, true);
      document.addEventListener("touchend", handle, {capture:true, passive:false});
    }
  }catch(e){
    console.error("wireCoreUI failed", e);
  }
}
async function startApp(){
  const btnLogout=document.getElementById('btnLogout'),btnLogoutApp=document.getElementById('btnLogoutApp');
  const installedApp = DSAuthSession.isStandalone();
  const workspaceLoginUid = installedApp ? DSAuthSession.takeWorkspaceLogin() : '';
  DSWorkflow.startupStatus('Firebase initialisieren');
  // Core UI wiring muss immer aktiv sein (auch wenn Cloud/Offline Pfad aktiv ist)
  wireCoreUI();
  // 1) Wenn Cloud aktiviert: Login + Sync
  const cloudOk = await cloudInit();
  if(!cloudOk){
    showAuthGate(true);
    setAuthMsg('Anmeldung nicht verfügbar. Bitte prüfe deine Internetverbindung.');
    dsSetSyncDiag('Firebase konnte nicht geladen werden. Anmeldung erforderlich.',true);
    return;
  }
  // GB22: Admin-Firebase-Session hart initialisieren, bevor die Haupt-App weiterläuft.
  try{
    const customerLocked = (typeof isCustomerMainDogsMode === 'function') ? !!isCustomerMainDogsMode() : false;
    const p = (location && location.pathname) ? location.pathname.toLowerCase() : '';
    const alreadyOnLogin = p.endsWith('login.html');
    if(!customerLocked && !alreadyOnLogin){
      const auth = CLOUD && CLOUD.auth ? CLOUD.auth : null;
      const current = (auth && auth.currentUser) ? auth.currentUser : null;
      if(current){
        try{ CLOUD.user = current; }catch(_){ }
      } else if(auth && auth.onAuthStateChanged){
        const settled = await new Promise((resolve)=>{
          let done = false;
          let unsub = null;
          const finish = (user)=>{
            if(done) return;
            done = true;
            try{ if(unsub) unsub(); }catch(_){ }
            resolve(user || null);
          };
          const t = setTimeout(()=>finish((auth && auth.currentUser) ? auth.currentUser : null), 2500);
          try{
            unsub = auth.onAuthStateChanged((user)=>{ clearTimeout(t); finish(user || null); });
          }catch(_){
            clearTimeout(t);
            finish((auth && auth.currentUser) ? auth.currentUser : null);
          }
        });
        if(settled){
          try{ CLOUD.user = settled; }catch(_){ }
        } else {
          const rel = (location.pathname.split('/').pop() || 'app.html') + (location.search || '') + (location.hash || '');
          try{ sessionStorage.setItem('ds_auth_required_return_to', rel); }catch(_){ }
          try{ location.replace('login.html?return_to=' + encodeURIComponent(rel)); }catch(_){ location.href = 'login.html?return_to=' + encodeURIComponent(rel); }
          return;
        }
      }
    }
  }catch(_){ }
  // (UI wiring erfolgt zentral in wireCoreUI())
  // Auth state
  CLOUD.auth.onAuthStateChanged(async (user)=>{
    try{
    const previousUid=CLOUD.user && CLOUD.user.uid;
    if(previousUid && previousUid!==(user && user.uid)){
      window.DSCalendarEvents?.reset();
      globalThis.DSAnalyticsView?.reset();
      DSWorkflow.resetAccount();
    }
    CLOUD.user = user || null;
    if(!user){
      showAuthGate(true);
      try{ const ba=document.querySelector(".bottom-actions"); if(ba) ba.style.display="none"; }catch(e){}
      CLOUD.role = 'guest';
      try{ CLOUD.user = null; }catch(_){ }
      try{ if(btnLogoutApp) btnLogoutApp.style.display = 'none'; }catch(e){}
      try{ if(btnLogout) btnLogout.style.display = 'none'; }catch(e){}
      updateSyncUI();
      try{
        const p = (location && location.pathname) ? location.pathname.toLowerCase() : '';
        const customerLocked = (typeof isCustomerMainDogsMode === 'function') ? !!isCustomerMainDogsMode() : false;
        const alreadyOnLogin = p.endsWith('login.html');
        const hardLogout = !!window.__dsLogoutInFlight;
        if(!alreadyOnLogin){
          if(hardLogout){
            try{ sessionStorage.removeItem('ds_auth_required_return_to'); }catch(_){ }
            try{ location.replace('login.html'); }catch(_){ location.href = 'login.html'; }
            return;
          }
          const rel = (location.pathname.split('/').pop() || 'app.html') + (location.search || '') + (location.hash || '');
          const target = 'login.html?return_to=' + encodeURIComponent(rel);
          try{ sessionStorage.setItem('ds_auth_required_return_to', rel); }catch(_){ }
          location.href = target;
          return;
        }
      }catch(e){}
      return;
    }
    try{ window.__dsLogoutInFlight = false; }catch(_){ }
    // Rolle (v2): aus Firestore (mit Whitelist-Override)
    try{
      DSWorkflow.startupStatus('Benutzerprofil laden');
      const loadedProfile=await loadOrCreateUserProfile(user);
      if(firebase.auth().currentUser?.uid!==user.uid)return;
      const role = DSWorkflow.workspaceRole(user,loadedProfile);
      if(installedApp && (role === ROLES.ADMIN || role === ROLES.STAFF)){
        if(user.uid !== workspaceLoginUid){
          await CLOUD.auth.signOut();
          return;
        }
        await CLOUD.auth.setPersistence(window.firebase.auth.Auth.Persistence.NONE);
        if(CLOUD.auth.currentUser?.uid!==user.uid)return;
      }
      CLOUD.userProfile=loadedProfile;
      await DSBrowserStore.prepare(window.firebaseConfig.projectId,CLOUD.orgId,user.uid);
      if(firebase.auth().currentUser?.uid!==user.uid)return;
      LS_KEY='ds_workspace_v3:'+window.firebaseConfig.projectId+':'+CLOUD.orgId+':'+user.uid;
      state=loadState();DSWorkflow.captureStartup(state);ensureStateShape();
      SYNC.cloudPending=Number(state._localUpdatedAt||0)>Number(state._cloudUpdatedAt||0);
      await DSWorkflow.watchProfile(user);
      if(firebase.auth().currentUser?.uid!==user.uid)return;
      DSWorkflow.startupStatus('Kundenprofil geladen');window.DSCustomerPortal?.ready();
      CLOUD.role=DSWorkflow.workspaceRole(user,CLOUD.userProfile);
      if(['admin','staff'].includes(CLOUD.role))window.DSCalendarEvents?.resumeDevice();
    }catch(e){
      console.warn('Role load failed; no staff fallback', e);
      const p=String((location&&location.pathname)||'').toLowerCase();
      const q=String((location&&location.search)||'');
      CLOUD.role='guest';DSWorkflow.resetAccount();
      SYNC.cloudLastError=e.message;updateSyncUI();DSWorkflow.startupStatus('Benutzerprofil konnte nicht geladen werden',e);dsSetSyncDiag(e.message,true);setAuthMsg(e.message);
    }
    try{
      if(CLOUD.role !== ROLES.CUSTOMER){
        try{ dsClearCustomerMainSessionArtifacts(); }catch(_){ }
        try{
          const cleanHref = (typeof dsGetNonCustomerCleanAppHref === 'function') ? dsGetNonCustomerCleanAppHref() : '';
          if(cleanHref){
            try{ sessionStorage.removeItem('ds_auth_required_return_to'); }catch(_e){}
            try{ location.replace(cleanHref); }catch(_e){ location.href = cleanHref; }
            return;
          }
        }catch(_e){ }
      }
    }catch(_){ }
    if(!['admin','staff','customer'].includes(CLOUD.role)){showAuthGate(true);return;}
    // Erzwungener Kundenmodus in Haupt-App via Query/Handoff
    const forcedCustomerMainMode = (typeof getCustomerMainModeLoose === 'function') ? getCustomerMainModeLoose() : '';
    if(forcedCustomerMainMode){
      try{ initCustomerMainDogsMode(); }catch(e){ console.error(e); }
      return;
    }
    // Kundenmodus: entweder Kundenportal oder eingeschränkte Haupt-App
    if(CLOUD.role === ROLES.CUSTOMER){
      try{ await initCustomerPortal(); }catch(e){ console.error(e); }
      return;
    }
    showAuthGate(false);
    DSWorkflow.startupStatus('Workspace laden');
    window.DSRepair?.install();
    try{
      const chatPanel = document.getElementById('panel-chat');
      if(chatPanel && chatPanel.classList.contains('is-active')) renderAdminChatPanel(true);
    }catch(_){ }
    // Cloud-Erreichbarkeit prüfen, damit Status nicht erst nach einer Aktion auf Online springt
    try{ scheduleCloudPing(50,'auth-login'); }catch(e){}
    if(btnLogout) btnLogout.style.display = "inline-block";
    if(btnLogoutApp) btnLogoutApp.style.display = "inline-block";
    updateSyncUI();
    if(btnLogoutApp) btnLogoutApp.style.display = "inline-block";
    // staff/admin Features (Rollen, Aufgaben, Inbox)
    try{ await initStaffFeatures(); }catch(e){ console.warn(e); }
    // Sync UI initial
    SYNC.cloudLastOkAt = Number(CLOUD.lastPushOkAt||0);
    SYNC.cloudLastError = String(CLOUD.lastPushError||"");
    updateSyncUI();
    
// Erstes Boot lokal (stellt state sicher), dann Remote zuverlässig einspielen
const bootReady=bootOnce();
bootReady.then(openCalendarReminder).catch(()=>{});
bootReady.catch(e=>{if(firebase.auth().currentUser?.uid===user.uid){SYNC.cloudLastError=e.message;updateSyncUI();DSWorkflow.startupStatus('Oberfläche konnte nicht starten',e);dsSetSyncDiag(e.message,true);}});
// Echtzeit-Listener (robust, inkl. erstem Snapshot)
// Wichtig: Listener so früh wie möglich setzen, damit der initiale State auch bei iOS/Safari sicher kommt.
try{
  if(CLOUD._unsubWorkspace){ try{ CLOUD._unsubWorkspace(); }catch(_){ } }
}catch(_){ }
try{
  const ref = cloudStateRef();
  if(ref && ref.onSnapshot){
    CLOUD._unsubWorkspace = ref.onSnapshot((snap)=>{
      if(!snap || !snap.exists || snap.metadata.hasPendingWrites || snap.metadata.fromCache || firebase.auth().currentUser?.uid!==user.uid)return;
      const data = snap.data() || {};
      const remotePayload = dsBuildMergedCloudDocPayload(data) || null;
      if(!remotePayload){SYNC.cloudLastError='Der Workspace-Serverstand enthält keinen gültigen Payload.';updateSyncUI();DSWorkflow.startupStatus('Workspace konnte nicht geladen werden',SYNC.cloudLastError);return;}
      CLOUD._workspaceReadConfirmedAt=Date.now();
      const stamp = Number(data.updatedAt || 0);
      if(stamp){ SYNC.cloudLastSeenAt = stamp; updateSyncUI(); }
      const localUpdated = Number(state && state._localUpdatedAt || 0);
      const localCloudStamp = Number(state && state._cloudUpdatedAt || 0);
      const localEmpty = isStateEffectivelyEmpty(state);
      const hasContractCanonical = dsRemoteHasContractCanonical(remotePayload);
      // Falls lokal leer (z.B. LocalStorage von iOS geleert) -> Remote sofort übernehmen.
      if(localEmpty && remotePayload){
        applyRemoteState(remotePayload, stamp, "snapshot-initial");
        return;
      }
      // GB342: Contract-Canonical-Daten müssen auch dann gemerged werden, wenn
      // der Snapshot von derselben Anmeldung stammt oder lokal scheinbar neuer ist.
      // Sonst gewinnt nach Logout/Login wieder der alte payload ohne Sonja/Bello.
      // Server revisions, not local UI-save timestamps, determine remote changes.
      if(!hasContractCanonical && stamp && stamp <= localCloudStamp) return;
      // Nicht unsere eigene Änderung nochmal einspielen (aber nur, wenn lokal NICHT leer ist)
      // Own administrator reviews also update the visible Workspace.
      if(remotePayload){
        applyRemoteState(remotePayload, stamp, hasContractCanonical ? "snapshot-contract-canonical" : "snapshot");
      }
    });
  }
}catch(e){
  console.warn("Workspace onSnapshot failed", e);
}
// Initial read never publishes a local fallback or prioritizes historic contract mirrors.
try{
  const {remote,err}=await cloudLoadStateWithRetry(3);
  if(firebase.auth().currentUser?.uid!==user.uid)return;
  if(!remote)throw err || new Error('Kein bestätigter Workspace-Serverstand vorhanden.');
  applyRemoteState(remote,Number(CLOUD._lastRemoteStamp || remote._cloudUpdatedAt || 0),'initial-read');
  CLOUD._startupLocalSnapshot=null;
  DSWorkflow.startupStatus(SYNC.cloudNeedsReview?'Lokale Änderungen prüfen':SYNC.cloudPending?'Übertragung ausstehend':'Workspace geladen');
}catch(e){
  SYNC.cloudLastError=e.message;updateSyncUI();DSWorkflow.startupStatus('Workspace konnte nicht geladen werden',e);dsSetSyncDiag(e.message,true);setAuthMsg('Serverstand konnte nicht geladen werden. Lokale Änderungen bleiben erhalten.');
}

    }catch(error){
      if(firebase.auth().currentUser?.uid!==user?.uid)return;
      SYNC.cloudLastError=error.message||String(error);updateSyncUI();
      DSWorkflow.startupStatus('Anwendungsstart fehlgeschlagen',error);dsSetSyncDiag(SYNC.cloudLastError,true);setAuthMsg(SYNC.cloudLastError);
      console.error('Workspace startup failed',error);
    }
  });
}
