function _statComputeIndexB(scales){return DSStatistics.index(scales);}

function _statInterpretIndex(idx){if(idx===null||!Number.isFinite(Number(idx)))return {band:'—',text:'Keine auswertbaren Skalen'};const n=Number(idx);return n<=3?{band:'1–3',text:'sehr stabil'}:n<=5?{band:'>3–5',text:'moderat'}:n<=7?{band:'>5–7',text:'erhöhte Belastung'}:{band:'>7–10',text:'kritisch / Interventionsbedarf'};}

// ---------- Firestore helpers ----------
function _statFs(){
  if(!(window.firebase && firebase.firestore)) throw new Error('firebase not available');
  // wenn Cloud aktiv ist, nutze die bereits initialisierte DB
  try{
    if(typeof CLOUD !== 'undefined' && CLOUD && CLOUD.enabled && CLOUD.db) return CLOUD.db;
  }catch(_){ }
  return firebase.firestore();
}
function _statUid(){
  try{
    return (firebase.auth && firebase.auth().currentUser) ? firebase.auth().currentUser.uid : null;
  }catch(_){ return null; }
}
function _statDocId(petId, dateISO, type){
  return `${petId}__${dateISO}__${type}`.replace(/[^a-zA-Z0-9_\-]/g, '_');
}
function _statColl(){
  const db = _statFs();
  const orgId = (typeof CLOUD !== 'undefined' && CLOUD?.orgId)
    ? CLOUD.orgId
    : 'doggystyle'; // org locked hard fallback

  return db.collection('orgs')
           .doc(orgId)
           .collection('statistics');
}

