function _statPetOptions(){return DSStatistics.pets().map(p=>({id:p.id,name:p.name||p.id}));}
function _statFillDogSelect(selId, firstLabel='Alle Hunde'){
  const sel = document.getElementById(selId);
  if(!sel) return;
  const opts = _statPetOptions();
  sel.innerHTML = `<option value="">${escapeHtml(firstLabel)}</option>` + opts.map(o=>`<option value="${escapeHtml(o.id)}">${escapeHtml(o.name)}</option>`).join('');
}

function initStatAnalysisBindings(){
  _statFillDogSelect('statAnaDog','Alle Hunde');

  const fromEl = document.getElementById('statAnaFrom');
  const toEl = document.getElementById('statAnaTo');
  const btn = document.getElementById('btnStatAnaLoad');
  if(fromEl && !fromEl.value){
    // default: last 30 days
    try{
      const d=new Date(); const to=toISODateLocal(d);
      const d2=new Date(); d2.setDate(d2.getDate()-30);
      fromEl.value = toISODateLocal(d2);
      toEl.value = to;
    }catch(_){ }
  }
  if(btn){
    btn.onclick = ()=>{ loadAndRenderStatAnalysis(); };
  }
  // V2.1+ (Rasse/Heatmap/Gruppen)
  _statFillBreedSelect('statBreedSel');

  const bBreed = document.getElementById('btnStatBreedRun');
  if(bBreed) bBreed.onclick = ()=>{ loadAndRenderStatBreedComparison(); };

  const bHeat = document.getElementById('btnStatHeatRun');
  if(bHeat) bHeat.onclick = ()=>{ loadAndRenderStatHeatmap(); };

  const bGroup = document.getElementById('btnStatGroupRun');
  if(bGroup) bGroup.onclick = ()=>{ loadAndRenderStatGroupPairs(); };

  const bAI = document.getElementById('btnStatGroupAIRun');
  if(bAI) bAI.onclick = ()=>{ loadAndRenderStatGroupAI(); };

  loadAndRenderStatAnalysis();
}

async function loadAndRenderStatAnalysis(){
  const msg = document.getElementById('statAnaMsg');
  const dogId = (document.getElementById('statAnaDog')||{}).value || '';
  const from = (document.getElementById('statAnaFrom')||{}).value || '';
  const to = (document.getElementById('statAnaTo')||{}).value || '';

  if(msg) msg.textContent='Lade…';

  try{
    const request=crypto.randomUUID();if(msg)msg.dataset.statRequest=request;const loaded = await _statLoadRange({from,to,dogId});if(msg&&(!msg.isConnected||msg.dataset.statRequest!==request))return;const rows=loaded.filter(r=>Number.isFinite(r.__indexB));

    if(!rows.length){
      if(msg) msg.textContent='Keine Daten im Zeitraum.';
      _statRenderAnalysisEmpty();
      return;
    }

    _statRenderAnalysis(rows);
    if(msg) msg.textContent = DSStatistics.readMessage(rows.length);

  }catch(e){
    console.error('[STAT] analysis load failed', e);
    if(msg)msg.textContent=e.message;
  }
}

/* ===========================
   Statistik V2.1+ Erweiterungen
   - Rassenvergleich
   - Heatmap
   - Gruppenanalyse / Gruppen-KI
   =========================== */

function _statFillBreedSelect(id){const sel=document.getElementById(id);if(!sel)return;sel.replaceChildren(new Option('Alle Rassen',''),...[...new Set(DSStatistics.pets().map(p=>p.breed||p.race).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'de')).map(b=>new Option(b,b)));}

function _statLocalFilterRange({from='', to='', breed='', dogId='' }={}){
  let rows = _statLocalRead();
  rows = (rows||[]).filter(r => r && (!dogId || String(r.dogId||r.petId||'') === String(dogId)));
  if(breed) rows = rows.filter(r => String(r.breed||'') === String(breed));
  if(from) rows = rows.filter(r => String(r.date||'') >= String(from));
  if(to) rows = rows.filter(r => String(r.date||'') <= String(to));
  rows.sort((a,b)=> String(a.date||'').localeCompare(String(b.date||'')));
  return rows.map(r=>{
    const sc = r.scores || r.scales || {};
    return { ...r, __scores: sc, __indexB: Number.isFinite(Number(r.indexB)) ? Number(r.indexB) : _statComputeIndexB(sc) };
  });
}

async function _statLoadRange(filters){return DSStatistics.read(filters);}

function _statAvg(arr){
  if(!arr || !arr.length) return 0;
  let s=0; arr.forEach(x=>{ s += (Number(x)||0); });
  return s/arr.length;
}

async function loadAndRenderStatBreedComparison(){
  const msg = document.getElementById('statBreedMsg');
  const table = document.getElementById('statBreedTable');
  const breed = (document.getElementById('statBreedSel')||{}).value || '';
  const from = (document.getElementById('statAnaFrom')||{}).value || '';
  const to = (document.getElementById('statAnaTo')||{}).value || '';

  if(msg) msg.textContent='Lade…';

  try{
    const request=crypto.randomUUID();if(msg)msg.dataset.statRequest=request;const loaded = await _statLoadRange({from,to,breed});if(msg&&(!msg.isConnected||msg.dataset.statRequest!==request))return;const rows=loaded.filter(r=>Number.isFinite(r.__indexB));
    if(!rows.length){
      if(msg) msg.textContent='Keine Daten im Zeitraum.';
      if(table) table.innerHTML = '<tr><th>Rasse</th><th style="text-align:right;">Ø IndexB</th><th style="text-align:right;">n</th></tr>';
      return;
    }

    const by = {};
    rows.forEach(r=>{
      const b = (r.breed || '—').toString().trim() || '—';
      (by[b] ||= []).push(r.__indexB);
    });

    const items = Object.keys(by).map(b=>({
      breed:b,
      n:by[b].length,
      avg:_statAvg(by[b])
    })).sort((a,b)=>b.avg-a.avg);

    if(table){
      table.innerHTML = '<tr><th>Rasse</th><th style="text-align:right;">Ø IndexB</th><th style="text-align:right;">n</th></tr>';
      items.forEach(it=>{
        const tr=document.createElement('tr');
        tr.innerHTML = `<td>${escapeHtml(it.breed)}</td><td style="text-align:right;">${it.avg.toFixed(2)}</td><td style="text-align:right;">${it.n}</td>`;
        table.appendChild(tr);
      });
    }

    if(msg) msg.textContent = `${rows.length} Einträge · ${items.length} Rassen.`;
    setTimeout(()=>{ if(msg) msg.textContent=''; }, 4000);
  }catch(e){
    console.error('[STAT] breed comparison failed', e);
    if(msg)msg.textContent=e.message;
  }
}

function _statHeatColor(v){
  const x = Number(v)||0;
  if(x >= 6) return '#ff5252';
  if(x >= 4) return '#ff9800';
  return '#4caf50';
}

async function loadAndRenderStatHeatmap(){
  const msg = document.getElementById('statHeatMsg');
  const box = document.getElementById('statHeatmap');
  const from = (document.getElementById('statAnaFrom')||{}).value || '';
  const to = (document.getElementById('statAnaTo')||{}).value || '';
  if(msg) msg.textContent='Lade…';

  try{
    const request=crypto.randomUUID();if(msg)msg.dataset.statRequest=request;const loaded = await _statLoadRange({from,to,breed:''});if(msg&&(!msg.isConnected||msg.dataset.statRequest!==request))return;const rows=loaded.filter(r=>Number.isFinite(r.__indexB));
    if(!rows.length){
      if(msg) msg.textContent='Keine Daten im Zeitraum.';
      if(box) box.innerHTML='';
      return;
    }

    const map = {};
    rows.forEach(r=>{
      const b = (r.breed || '—').toString().trim() || '—';
      const d = (r.date || '').toString();
      if(!d) return;
      const key = b + '||' + d;
      (map[key] ||= []).push(r.__indexB);
    });

    const cells = Object.keys(map).map(k=>{
      const parts = k.split('||');
      const breed = parts[0];
      const date = parts[1];
      const avg = _statAvg(map[k]);
      return {breed,date,avg};
    }).sort((a,b)=>{
      const c = a.breed.localeCompare(b.breed,'de');
      if(c!==0) return c;
      return a.date.localeCompare(b.date);
    });

    if(box){
      box.innerHTML='';
      cells.forEach(c=>{
        const div=document.createElement('div');
        div.className='heat-cell';
        div.style.background = _statHeatColor(c.avg);
        div.innerHTML = `<div class="heat-breed">${escapeHtml(c.breed)}</div>
                         <div class="heat-date">${escapeHtml(c.date)}</div>
                         <div class="heat-val">${c.avg.toFixed(2)}</div>`;
        box.appendChild(div);
      });
    }

    if(msg) msg.textContent = `${cells.length} Felder (Ø je Rasse/Tag).`;
    setTimeout(()=>{ if(msg) msg.textContent=''; }, 4000);
  }catch(e){
    console.error('[STAT] heatmap failed', e);
    if(msg)msg.textContent=e.message;
  }
}

function _statPairKey(a,b){
  a=String(a); b=String(b);
  return (a < b) ? (a+'_'+b) : (b+'_'+a);
}

function _statBuildPairStats(rows){
      const pairs=new Map();let used=0;for(const r of rows){const dogs=[...new Set((r.dogsInGroup||[]).map(String).filter(Boolean))].sort();if(dogs.length<2||!Number.isFinite(r.__indexB))continue;used++;
        for(let i=0;i<dogs.length;i++)for(let j=i+1;j<dogs.length;j++){const ids=[dogs[i],dogs[j]],key=JSON.stringify(ids),a=pairs.get(key)||{ids,values:[]};a.values.push(r.__indexB);pairs.set(key,a);}}
      const list=[...pairs.values()].map(x=>({pair:x.ids.map(_statDogLabelById).join(' + '),avg:x.values.reduce((a,b)=>a+b,0)/x.values.length,n:x.values.length})).sort((a,b)=>b.avg-a.avg);return{list,used};
    }

async function loadAndRenderStatGroupPairs(){
  const msg = document.getElementById('statGroupMsg');
  const host = document.getElementById('statGroupList');
  const from = (document.getElementById('statAnaFrom')||{}).value || '';
  const to = (document.getElementById('statAnaTo')||{}).value || '';
  if(msg) msg.textContent='Lade…';

  try{
    const request=crypto.randomUUID();if(msg)msg.dataset.statRequest=request;const loaded = await _statLoadRange({from,to,breed:''});if(msg&&(!msg.isConnected||msg.dataset.statRequest!==request))return;const rows=loaded.filter(r=>Number.isFinite(r.__indexB));
    if(!rows.length){
      if(msg) msg.textContent='Keine Daten im Zeitraum.';
      if(host) host.innerHTML='';
      return;
    }

    const {list, used} = _statBuildPairStats(rows);

    if(host){
      host.innerHTML='';
      const top = list.slice(0, 25);
      if(!top.length){
        host.innerHTML = '<div class="muted" style="font-size:12px;">Keine gemeinsamen Beobachtungen im Zeitraum. Bei der Erfassung die tatsächlich beobachteten Gruppenmitglieder auswählen.</div>';
      }else{
        top.forEach(it=>{
          const div=document.createElement('div');
          div.className='item';
          const lvl = it.avg>=6 ? '⛔' : (it.avg>=4 ? '⚠️' : '✅');
          div.innerHTML = `<div style="display:flex; justify-content:space-between; gap:10px;">
                             <div><strong>${lvl} ${escapeHtml(it.pair)}</strong><div class="muted" style="font-size:12px;">Messungen: ${it.n}</div></div>
                             <div style="font-weight:800;">${it.avg.toFixed(2)}</div>
                           </div>`;
          host.appendChild(div);
        });
      }
    }

    if(msg) msg.textContent = `${used} Gruppen-Einträge genutzt · ${list.length} Paare.`;
    setTimeout(()=>{ if(msg) msg.textContent=''; }, 5000);
  }catch(e){
    console.error('[STAT] group pairs failed', e);
    if(msg)msg.textContent=e.message;
  }
}

async function loadAndRenderStatGroupAI(){
  const msg = document.getElementById('statGroupAIMsg');
  const goodHost = document.getElementById('statGroupGood');
  const badHost = document.getElementById('statGroupBad');
  const from = (document.getElementById('statAnaFrom')||{}).value || '';
  const to = (document.getElementById('statAnaTo')||{}).value || '';
  if(msg) msg.textContent='Lade…';

  try{
    const request=crypto.randomUUID();if(msg)msg.dataset.statRequest=request;const loaded = await _statLoadRange({from,to,breed:''});if(msg&&(!msg.isConnected||msg.dataset.statRequest!==request))return;const rows=loaded.filter(r=>Number.isFinite(r.__indexB));
    if(!rows.length){
      if(msg) msg.textContent='Keine Daten im Zeitraum.';
      if(goodHost) goodHost.innerHTML='';
      if(badHost) badHost.innerHTML='';
      return;
    }

    const {list, used} = _statBuildPairStats(rows);

    const good = list.filter(x=>x.avg < 4).sort((a,b)=>a.avg-b.avg).slice(0, 15);
    const bad = list.filter(x=>x.avg >= 6).sort((a,b)=>b.avg-a.avg).slice(0, 15);

    const renderList = (host, arr, icon)=>{
      if(!host) return;
      host.innerHTML='';
      if(!arr.length){
        host.innerHTML = `<div class="muted" style="font-size:12px;">Keine ${icon==='✅'?'klaren Empfehlungen':'klaren Höhere beobachtete Belastung'} im Zeitraum.</div>`;
        return;
      }
      arr.forEach(it=>{
        const div=document.createElement('div');
        div.className='item';
        div.innerHTML = `<div style="display:flex; justify-content:space-between; gap:10px;">
                           <div><strong>${icon} ${escapeHtml(it.pair)}</strong><div class="muted" style="font-size:12px;">Messungen: ${it.n}</div></div>
                           <div style="font-weight:800;">${it.avg.toFixed(2)}</div>
                         </div>`;
        host.appendChild(div);
      });
    };

    renderList(goodHost, good, '✅');
    renderList(badHost, bad, '⛔');

    if(msg) msg.textContent = `${used} Gruppen-Einträge genutzt · ${list.length} Paare ausgewertet.`;
    setTimeout(()=>{ if(msg) msg.textContent=''; }, 5000);
  }catch(e){
    console.error('[STAT] group AI failed', e);
    if(msg)msg.textContent=e.message;
  }
}


function _statRenderAnalysisEmpty(){
  const c=document.getElementById('statAnaChart');
  if(c){
    const ctx=c.getContext('2d');
    ctx.clearRect(0,0,c.width,c.height);
    ctx.font='12px sans-serif';
    ctx.fillText('Keine Daten', 10, 20);
  }
  const sum=document.getElementById('statAnaSummary');
  if(sum) sum.innerHTML = '<div class="muted">—</div>';
  const avg=document.getElementById('statAnaAvgTable');
  if(avg) avg.innerHTML = '<tr><th>Kategorie</th><th style="text-align:right;">Ø (1–10)</th></tr>';
  const raw=document.getElementById('statAnaRawTable');
  if(raw) raw.innerHTML = '';
  const hint=document.getElementById('statAnaIndexHint');
  if(hint) hint.textContent='';
}

function _statRenderAnalysis(rows){
  rows=rows.filter(r=>Number.isFinite(r.__indexB));if(!rows.length){_statRenderAnalysisEmpty();return;}
  // Summary stats
  const idxs = rows.map(r=>r.__indexB).filter(v=>Number.isFinite(v));
  const mean = idxs.reduce((a,b)=>a+b,0)/Math.max(1,idxs.length);
  const last = idxs[idxs.length-1];
  const interp = _statInterpretIndex(mean);
  const hint = document.getElementById('statAnaIndexHint');
  if(hint){
    hint.textContent = `Ø Index: ${mean.toFixed(1)} (${interp.text})`;
  }

  // Trend: last 3 vs previous 3
  let trendTxt='Trend: —';
  if(idxs.length>=6){
    const a = idxs.slice(-3).reduce((x,y)=>x+y,0)/3;
    const b = idxs.slice(-6,-3).reduce((x,y)=>x+y,0)/3;
    const diff = a-b;
    if(Math.abs(diff)<0.2) trendTxt='Trend: stabil';
    else if(diff>0) trendTxt=`Trend: steigend (+${diff.toFixed(1)})`;
    else trendTxt=`Trend: fallend (${diff.toFixed(1)})`;
  }

  const sum=document.getElementById('statAnaSummary');
  if(sum){
    const li = _statInterpretIndex(last);
    sum.innerHTML = `
      <div class="row" style="flex-wrap:wrap; gap:12px;">
        <div class="card" style="flex:1; min-width:220px;">
          <div class="muted" style="font-size:12px;">Letzter Index</div>
          <div style="font-size:26px; font-weight:700;">${Number.isFinite(last)? last.toFixed(1):'—'}</div>
          <div class="muted" style="font-size:12px;">${escapeHtml(li.text)}</div>
        </div>
        <div class="card" style="flex:1; min-width:220px;">
          <div class="muted" style="font-size:12px;">Ø Index (Zeitraum)</div>
          <div style="font-size:26px; font-weight:700;">${mean.toFixed(1)}</div>
          <div class="muted" style="font-size:12px;">${escapeHtml(interp.text)} · ${escapeHtml(trendTxt)}</div>
        </div>
        <div class="card" style="flex:2; min-width:240px;">
          <div class="muted" style="font-size:12px;">Interpretation</div>
          <div style="margin-top:6px; font-size:13px; line-height:1.35;">
            1–3 sehr stabil · 4–5 moderat · 6–7 erhöhte Belastung · 8–10 kritisch / Interventionsbedarf
          </div>
        </div>
      </div>
    `;
  }

  // Avg per dimension
  const sums = {}; const counts = {};
  STAT_DIMENSIONS.forEach(d=>{ sums[d.id]=0; counts[d.id]=0; });
  rows.forEach(r=>{
    STAT_DIMENSIONS.forEach(d=>{
      const v = DSStatistics.number(r.__scores?.[d.id]);
      if(Number.isFinite(v)){
        sums[d.id]+=v; counts[d.id]+=1;
      }
    });
  });
  const avgTable=document.getElementById('statAnaAvgTable');
  if(avgTable){
    avgTable.innerHTML = '<tr><th>Kategorie</th><th style="text-align:right;">Ø (1–10)</th></tr>' +
      STAT_DIMENSIONS.map(d=>{
        const c=counts[d.id]||0;
        const v=c? (sums[d.id]/c): null;
        return `<tr><td>${escapeHtml(d.label)}</td><td style="text-align:right;">${v==null?'—':v.toFixed(1)}</td></tr>`;
      }).join('');
  }

  // Raw table (compact)
  const raw=document.getElementById('statAnaRawTable');
  if(raw){
    const head = `
      <tr>
        <th>Datum</th><th>Typ</th>
        <th style="text-align:right;">Index</th>
        ${STAT_DIMENSIONS.map(d=>`<th style="text-align:right;">${escapeHtml(d.label)}</th>`).join('')}
      </tr>`;
    const body = rows.slice(-20).map(r=>{
      return `<tr>
        <td>${escapeHtml(r.date||'')}</td>
        <td>${escapeHtml(r.type||'')}</td>
        <td style="text-align:right;">${Number.isFinite(r.__indexB)? r.__indexB.toFixed(1):'—'}</td>
        ${STAT_DIMENSIONS.map(d=>{
          const v = DSStatistics.number(r.__scores?.[d.id]);
          return `<td style="text-align:right;">${Number.isFinite(v)? v: '—'}</td>`;
        }).join('')}
      </tr>`;
    }).join('');
    raw.innerHTML = head + body;
  }

  // Chart (simple line)
  _statDrawLineChart('statAnaChart', rows.map(r=>({x:r.date, y:r.__indexB})));
}

function _statDrawLineChart(canvasId, points){
  const c = document.getElementById(canvasId);
  if(!c) return;
  const ctx = c.getContext('2d');if(!ctx)return;ctx.strokeStyle='#d4a34f';ctx.fillStyle='#eee';

  // handle high-dpi
  const rect = c.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  c.width = Math.max(300, Math.floor(rect.width * dpr));
  c.height = Math.max(120, Math.floor(120 * dpr));
  ctx.scale(dpr, dpr);

  const w = rect.width;
  const h = 120;

  ctx.clearRect(0,0,w,h);

  // grid
  ctx.globalAlpha = 0.25;
  ctx.beginPath();
  for(let i=0;i<=5;i++){
    const y = 10 + (h-20)*(i/5);
    ctx.moveTo(10,y); ctx.lineTo(w-10,y);
  }
  ctx.stroke();
  ctx.globalAlpha = 1;

  const vals = points.map(p=>p.y).filter(v=>Number.isFinite(v));
  if(!vals.length){
    ctx.font='12px sans-serif';
    ctx.fillText('Keine Index-Werte', 10, 20);
    return;
  }

  const minY = 1;
  const maxY = 10;

  const xs = points.map((p,i)=>i);
  const n = points.length;
  const xToPx = (i)=> 10 + (w-20) * (n<=1? 0 : (i/(n-1)));
  const yToPx = (v)=> 10 + (h-20) * (1 - ((v-minY)/(maxY-minY)));

  ctx.lineWidth = 2;
  ctx.beginPath();
  points.forEach((p,i)=>{
    const v = p.y;
    if(!Number.isFinite(v)) return;
    const x = xToPx(i);
    const y = yToPx(v);
    if(i===0) ctx.moveTo(x,y);
    else ctx.lineTo(x,y);
  });
  ctx.stroke();

  // points
  ctx.lineWidth = 1;
  points.forEach((p,i)=>{
    const v = p.y;
    if(!Number.isFinite(v)) return;
    const x=xToPx(i), y=yToPx(v);
    ctx.beginPath(); ctx.arc(x,y,3,0,Math.PI*2); ctx.fill();
  });

  // y labels
  ctx.font='11px sans-serif';
  ctx.globalAlpha=0.7;
  ctx.fillText('10', 12, 14);
  ctx.fillText('1', 12, h-8);
  ctx.globalAlpha=1;
}

